// AUTO-GENERATED grammar reference for HSK 1-9 (key grammar points per level).
// Generated by multi-agent authoring; safe to regenerate or hand-edit.
(function (root, factory) {
  const api = factory();
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else root.GRAMMAR = api;
})(typeof self !== "undefined" ? self : this, function () {
  return {"1":[{"title":"Stating identity with 是","pattern":"Subject + 是 + Noun","explanation":"Use 是 (shì) to equate two nouns, similar to English 'is/am/are'. Unlike English, 是 is not used with adjectives — only with nouns or noun phrases.","examples":[{"cn":"我是学生。","py":"Wǒ shì xuéshēng.","en":"I am a student."},{"cn":"她是老师。","py":"Tā shì lǎoshī.","en":"She is a teacher."},{"cn":"这是书。","py":"Zhè shì shū.","en":"This is a book."}]},{"title":"Negation with 不","pattern":"Subject + 不 + Verb/Adjective","explanation":"Place 不 (bù) directly before a verb or adjective to negate it. Note: 不 becomes bú before a fourth-tone syllable due to tone sandhi.","examples":[{"cn":"我不是医生。","py":"Wǒ bú shì yīshēng.","en":"I am not a doctor."},{"cn":"他不喝茶。","py":"Tā bù hē chá.","en":"He doesn't drink tea."},{"cn":"这不好。","py":"Zhè bù hǎo.","en":"This is not good."}]},{"title":"Yes/No questions with 吗","pattern":"Statement + 吗？","explanation":"Add 吗 (ma) to the end of any statement to turn it into a yes/no question. No other word order changes are needed.","examples":[{"cn":"你是学生吗？","py":"Nǐ shì xuéshēng ma?","en":"Are you a student?"},{"cn":"她喝水吗？","py":"Tā hē shuǐ ma?","en":"Does she drink water?"},{"cn":"这是你的书吗？","py":"Zhè shì nǐ de shū ma?","en":"Is this your book?"}]},{"title":"Possessive with 的","pattern":"Pronoun/Noun + 的 + Noun","explanation":"The particle 的 (de) marks possession, similar to 's in English. Between pronouns and close relationships (family/friends), 的 is often omitted.","examples":[{"cn":"这是我的手机。","py":"Zhè shì wǒ de shǒujī.","en":"This is my mobile phone."},{"cn":"他的名字是大卫。","py":"Tā de míngzi shì Dàwèi.","en":"His name is David."},{"cn":"那是老师的书。","py":"Nà shì lǎoshī de shū.","en":"That is the teacher's book."}]},{"title":"Existence and possession with 有","pattern":"Subject + 有 + Object","explanation":"有 (yǒu) means both 'to have' (possession) and 'there is/are' (existence). It is always negated with 没, never with 不.","examples":[{"cn":"我有一个哥哥。","py":"Wǒ yǒu yī gè gēgē.","en":"I have an older brother."},{"cn":"桌子上有水。","py":"Zhuōzi shàng yǒu shuǐ.","en":"There is water on the table."},{"cn":"他没有钱。","py":"Tā méiyǒu qián.","en":"He doesn't have any money."}]},{"title":"Negation of 有 with 没","pattern":"Subject + 没有 + Noun/Verb","explanation":"没 (méi) is used to negate 有 and also to negate past or completed actions. Never use 不 with 有.","examples":[{"cn":"我没有猫。","py":"Wǒ méiyǒu māo.","en":"I don't have a cat."},{"cn":"她没有来。","py":"Tā méiyǒu lái.","en":"She didn't come."},{"cn":"桌子上没有书。","py":"Zhuōzi shàng méiyǒu shū.","en":"There are no books on the table."}]},{"title":"General-purpose measure word 个","pattern":"Number + 个 + Noun","explanation":"Chinese requires a measure word between a number and a noun. 个 (gè) is the most common all-purpose measure word and can be used with people and many objects.","examples":[{"cn":"我有两个苹果。","py":"Wǒ yǒu liǎng gè píngguǒ.","en":"I have two apples."},{"cn":"他有三个朋友。","py":"Tā yǒu sān gè péngyǒu.","en":"He has three friends."},{"cn":"请给我一个杯子。","py":"Qǐng gěi wǒ yī gè bēizi.","en":"Please give me a cup."}]},{"title":"Question words 什么 / 谁 / 哪","pattern":"Subject + Verb + 什么/谁/哪 + (Noun)?","explanation":"Question words in Chinese stay in the same position as the answer would occupy — they do not move to the front of the sentence as in English.","examples":[{"cn":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","en":"What is your name?"},{"cn":"那是谁？","py":"Nà shì shuí?","en":"Who is that?"},{"cn":"你是哪国人？","py":"Nǐ shì nǎ guó rén?","en":"What country are you from?"}]},{"title":"Location with 在","pattern":"Subject + 在 + Place","explanation":"在 (zài) indicates where someone or something is located. As a verb it means 'to be at/in'. It can also precede a verb to mean the action takes place at a location.","examples":[{"cn":"他在家。","py":"Tā zài jiā.","en":"He is at home."},{"cn":"书在桌子上。","py":"Shū zài zhuōzi shàng.","en":"The book is on the table."},{"cn":"我在学校工作。","py":"Wǒ zài xuéxiào gōngzuò.","en":"I work at a school."}]},{"title":"Expressing likes with 喜欢","pattern":"Subject + 喜欢 + Noun/Verb","explanation":"喜欢 (xǐhuān) means 'to like'. It can be followed directly by a noun or a verb (verb phrase) with no extra words needed.","examples":[{"cn":"我喜欢猫。","py":"Wǒ xǐhuān māo.","en":"I like cats."},{"cn":"她喜欢喝咖啡。","py":"Tā xǐhuān hē kāfēi.","en":"She likes to drink coffee."},{"cn":"你喜欢什么？","py":"Nǐ xǐhuān shénme?","en":"What do you like?"}]},{"title":"Time expressions before the verb","pattern":"Subject + Time Word + Verb + Object","explanation":"In Chinese, time words come before the main verb, not after it as in English. They typically follow the subject but precede the verb.","examples":[{"cn":"我今天去学校。","py":"Wǒ jīntiān qù xuéxiào.","en":"I am going to school today."},{"cn":"她明天来。","py":"Tā míngtiān lái.","en":"She is coming tomorrow."},{"cn":"我们现在吃饭。","py":"Wǒmen xiànzài chīfàn.","en":"We are eating now."}]},{"title":"Adjective predicates (no 是 needed)","pattern":"Subject + (很) + Adjective","explanation":"Adjectives can directly act as predicates without 是. In neutral statements, 很 (hěn, 'very') is placed before the adjective — without it, the sentence implies a comparison. 很 here is often unstressed and does not strongly mean 'very'.","examples":[{"cn":"她很漂亮。","py":"Tā hěn piàoliang.","en":"She is pretty."},{"cn":"这个苹果很好吃。","py":"Zhège píngguǒ hěn hǎochī.","en":"This apple is delicious."},{"cn":"今天不冷。","py":"Jīntiān bù lěng.","en":"Today is not cold."}]}],"2":[{"title":"Completed Action with 了 (le)","pattern":"Subject + Verb + 了 + Object","explanation":"Place 了 immediately after the verb to mark that an action has been completed. This differs from past tense in English — 了 signals completion, not just past time.","examples":[{"cn":"我吃了早饭。","py":"Wǒ chī le zǎofàn.","en":"I ate breakfast (and finished it)."},{"cn":"她买了一本书。","py":"Tā mǎi le yī běn shū.","en":"She bought a book."},{"cn":"他们喝了茶。","py":"Tāmen hē le chá.","en":"They drank tea."}]},{"title":"Negative Completed Action with 没(有)","pattern":"Subject + 没(有) + Verb + Object","explanation":"Use 没(有) instead of 不 to negate a completed action. Do not use 了 when negating with 没有.","examples":[{"cn":"我没有吃早饭。","py":"Wǒ méiyǒu chī zǎofàn.","en":"I didn't eat breakfast."},{"cn":"他没买书。","py":"Tā méi mǎi shū.","en":"He didn't buy a book."},{"cn":"她没来学校。","py":"Tā méi lái xuéxiào.","en":"She didn't come to school."}]},{"title":"Experiential 过 (guò)","pattern":"Subject + Verb + 过 + Object","explanation":"Place 过 after the verb to express that someone has had the experience of doing something at least once in their life. Negate with 没(有) + Verb + 过.","examples":[{"cn":"我去过北京。","py":"Wǒ qù guò Běijīng.","en":"I have been to Beijing (before)."},{"cn":"你吃过饺子吗？","py":"Nǐ chī guò jiǎozi ma?","en":"Have you ever eaten dumplings?"},{"cn":"她没有学过中文。","py":"Tā méiyǒu xué guò Zhōngwén.","en":"She has never studied Chinese."}]},{"title":"Progressive Action with 正在/在","pattern":"Subject + 正在/在 + Verb + (Object) + 呢","explanation":"Use 正在 or 在 before the verb to show an action is in progress right now. 呢 at the end is optional but reinforces the ongoing sense.","examples":[{"cn":"我正在看书呢。","py":"Wǒ zhèngzài kàn shū ne.","en":"I am reading a book right now."},{"cn":"他们在吃饭。","py":"Tāmen zài chīfàn.","en":"They are eating."},{"cn":"妈妈在做什么呢？","py":"Māma zài zuò shénme ne?","en":"What is Mom doing?"}]},{"title":"Comparison with 比","pattern":"A + 比 + B + Adjective","explanation":"Use 比 between two items to say A is more [adjective] than B. Do not add 更 or 非常 directly after 比 + B; you can add 更 before the adjective for emphasis.","examples":[{"cn":"他比我高。","py":"Tā bǐ wǒ gāo.","en":"He is taller than me."},{"cn":"今天比昨天冷。","py":"Jīntiān bǐ zuótiān lěng.","en":"Today is colder than yesterday."},{"cn":"这个苹果比那个大。","py":"Zhège píngguǒ bǐ nàge dà.","en":"This apple is bigger than that one."}]},{"title":"Negative Comparison with 没有","pattern":"A + 没有 + B + Adjective","explanation":"Use 没有 to say A is not as [adjective] as B — the opposite of 比. This is the standard way to make a 'less than' comparison.","examples":[{"cn":"我没有他高。","py":"Wǒ méiyǒu tā gāo.","en":"I am not as tall as him."},{"cn":"这本书没有那本有意思。","py":"Zhè běn shū méiyǒu nà běn yǒuyìsi.","en":"This book is not as interesting as that one."},{"cn":"今天没有昨天冷。","py":"Jīntiān méiyǒu zuótiān lěng.","en":"Today is not as cold as yesterday."}]},{"title":"Modal Verbs: 想, 要, 会, 能","pattern":"Subject + 想/要/会/能 + Verb + Object","explanation":"These four modals each have distinct meanings: 想 (want to / feel like), 要 (want to / need to / will), 会 (have learned ability), 能 (have capacity/permission). They always precede the main verb.","examples":[{"cn":"我想喝水。","py":"Wǒ xiǎng hē shuǐ.","en":"I want to drink water."},{"cn":"她会说中文。","py":"Tā huì shuō Zhōngwén.","en":"She can speak Chinese (she has learned it)."},{"cn":"你能帮我吗？","py":"Nǐ néng bāng wǒ ma?","en":"Can you help me?"}]},{"title":"Degree Complement with 得","pattern":"Verb + 得 + Adjective/Adverb phrase","explanation":"Place 得 after a verb to introduce a complement that describes how well or to what degree the action was performed. To negate, put 不 after 得.","examples":[{"cn":"他说得很好。","py":"Tā shuō de hěn hǎo.","en":"He speaks very well."},{"cn":"她跑得快不快？","py":"Tā pǎo de kuài bu kuài?","en":"Does she run fast?"},{"cn":"我写得不太好。","py":"Wǒ xiě de bù tài hǎo.","en":"I don't write very well."}]},{"title":"Cause and Effect: 因为…所以…","pattern":"因为 + Reason clause + 所以 + Result clause","explanation":"Use 因为 to introduce a cause and 所以 to introduce the result. Both clauses can appear in the same sentence; in casual speech one of the two can be dropped.","examples":[{"cn":"因为下雨，所以我没有去。","py":"Yīnwèi xià yǔ, suǒyǐ wǒ méiyǒu qù.","en":"Because it rained, I didn't go."},{"cn":"因为他很累，所以早睡了。","py":"Yīnwèi tā hěn lèi, suǒyǐ zǎo shuì le.","en":"Because he was very tired, he went to bed early."},{"cn":"因为我喜欢中文，所以每天学习。","py":"Yīnwèi wǒ xǐhuān Zhōngwén, suǒyǐ měitiān xuéxí.","en":"Because I like Chinese, I study every day."}]},{"title":"Simultaneous Actions: 一边…一边…","pattern":"Subject + 一边 + Verb1 + 一边 + Verb2","explanation":"Use 一边…一边… to say that a subject does two actions at the same time. Both verbs should describe ongoing, compatible activities.","examples":[{"cn":"他一边吃饭一边看电视。","py":"Tā yībiān chīfàn yībiān kàn diànshì.","en":"He eats while watching TV."},{"cn":"她一边唱歌一边跳舞。","py":"Tā yībiān chàng gē yībiān tiào wǔ.","en":"She sings while dancing."},{"cn":"我一边走路一边听音乐。","py":"Wǒ yībiān zǒulù yībiān tīng yīnyuè.","en":"I listen to music while walking."}]},{"title":"Distance with 离","pattern":"Place A + 离 + Place B + (远/近/多远)","explanation":"Use 离 to express the distance or spatial separation between two places. The adjective (远 far, 近 near) or a distance phrase follows.","examples":[{"cn":"我家离学校很近。","py":"Wǒ jiā lí xuéxiào hěn jìn.","en":"My home is very close to the school."},{"cn":"银行离这里远吗？","py":"Yínháng lí zhèlǐ yuǎn ma?","en":"Is the bank far from here?"},{"cn":"图书馆离我家不太远。","py":"Túshūguǎn lí wǒ jiā bù tài yuǎn.","en":"The library is not too far from my home."}]},{"title":"From … To … with 从…到…","pattern":"从 + Start point + 到 + End point + Verb phrase","explanation":"Use 从…到… to express a range in time or space — from one point to another. It can frame the entire sentence or appear within it.","examples":[{"cn":"从家到公司要三十分钟。","py":"Cóng jiā dào gōngsī yào sānshí fēnzhōng.","en":"It takes thirty minutes from home to the office."},{"cn":"我从八点到十点学习。","py":"Wǒ cóng bā diǎn dào shí diǎn xuéxí.","en":"I study from eight o'clock to ten o'clock."},{"cn":"从北京到上海多远？","py":"Cóng Běijīng dào Shànghǎi duō yuǎn?","en":"How far is it from Beijing to Shanghai?"}]},{"title":"Beneficiary/Recipient with 给","pattern":"Subject + 给 + Person + Verb + Object  OR  Subject + Verb + 给 + Person + Object","explanation":"给 can act as a preposition meaning 'for/to (a person)' before the verb, or as a verb-complement after the verb to indicate transfer to a recipient.","examples":[{"cn":"我给她打了电话。","py":"Wǒ gěi tā dǎ le diànhuà.","en":"I called her."},{"cn":"他送给我一个礼物。","py":"Tā sòng gěi wǒ yī gè lǐwù.","en":"He gave me a gift."},{"cn":"请你给我看看。","py":"Qǐng nǐ gěi wǒ kàn kàn.","en":"Please take a look for me."}]},{"title":"Change of State 了 at Sentence End","pattern":"Statement + 了","explanation":"When 了 appears at the end of a sentence (rather than after a verb), it signals a change of state or a new situation — something is now different from before. It often translates as 'now' or 'already'.","examples":[{"cn":"他是老师了。","py":"Tā shì lǎoshī le.","en":"He is a teacher now (he became one)."},{"cn":"春天了，天气暖和了。","py":"Chūntiān le, tiānqì nuǎnhuo le.","en":"It's spring now; the weather has become warm."},{"cn":"我不想喝了。","py":"Wǒ bù xiǎng hē le.","en":"I don't want to drink anymore."}]}],"3":[{"title":"把 sentence (disposal construction)","pattern":"Subject + 把 + Object + Verb + Complement/Result","explanation":"把 moves the object before the verb to emphasize what is done to it or how it is disposed of. The verb must be followed by a result complement, direction complement, or other element — a bare verb after 把 is ungrammatical.","examples":[{"cn":"我把作业做完了。","py":"Wǒ bǎ zuòyè zuò wán le.","en":"I finished (doing) my homework."},{"cn":"他把书放在桌子上了。","py":"Tā bǎ shū fàng zài zhuōzi shàng le.","en":"He put the book on the table."},{"cn":"请你把门关上。","py":"Qǐng nǐ bǎ mén guān shàng.","en":"Please close the door."}]},{"title":"被 passive construction","pattern":"Subject + 被 + Agent + Verb + Complement","explanation":"被 marks the subject as the receiver of an action performed by the agent. It often carries a negative or undesirable connotation, and the verb typically requires a complement or aspect marker.","examples":[{"cn":"我的钱包被人偷走了。","py":"Wǒ de qiánbāo bèi rén tōu zǒu le.","en":"My wallet was stolen by someone."},{"cn":"这个问题被老师解决了。","py":"Zhège wèntí bèi lǎoshī jiějué le.","en":"This problem was solved by the teacher."},{"cn":"他被妈妈骂了一顿。","py":"Tā bèi māma mà le yī dùn.","en":"He was scolded by his mother."}]},{"title":"Result complement (结果补语)","pattern":"Verb + 完 / 懂 / 好 / 到 / 错 (+ Object)","explanation":"A result complement directly follows the verb and indicates the outcome of the action. Common complements include 完 (finished), 懂 (understood), 好 (done well), 到 (achieved/reached), and 错 (done wrongly).","examples":[{"cn":"我听懂了老师说的话。","py":"Wǒ tīng dǒng le lǎoshī shuō de huà.","en":"I understood what the teacher said."},{"cn":"作业写完了吗？","py":"Zuòyè xiě wán le ma?","en":"Have you finished writing the homework?"},{"cn":"你写错了一个字。","py":"Nǐ xiě cuò le yī gè zì.","en":"You wrote one character wrong."}]},{"title":"Directional complement (趋向补语)","pattern":"Verb + 上来 / 下去 / 起来 / 出去 / 进来 + (了)","explanation":"Directional complements describe the direction of movement relative to the speaker or a reference point. 起来 can also indicate the start of an action or a state, and 下去 can indicate continuation.","examples":[{"cn":"他从楼下跑上来了。","py":"Tā cóng lóuxià pǎo shàng lái le.","en":"He ran up from downstairs."},{"cn":"天气冷起来了。","py":"Tiānqì lěng qǐlái le.","en":"The weather has started to get cold."},{"cn":"你要坚持下去。","py":"Nǐ yào jiānchí xià qù.","en":"You need to keep going (persevere)."}]},{"title":"的 / 得 / 地 distinction","pattern":"Noun modifier + 的 + Noun | Verb + 得 + Degree complement | Adverb + 地 + Verb","explanation":"These three homophonous particles have distinct grammatical roles: 的 links adjectives or clauses to nouns, 得 introduces degree or result complements after verbs, and 地 links adverbs or adjective phrases to verbs.","examples":[{"cn":"她是一个聪明的学生。","py":"Tā shì yī gè cōngmíng de xuésheng.","en":"She is a clever student. (的 modifies noun)"},{"cn":"他跑得很快。","py":"Tā pǎo de hěn kuài.","en":"He runs very fast. (得 introduces degree complement)"},{"cn":"她高兴地笑了。","py":"Tā gāoxìng de xiào le.","en":"She laughed happily. (地 links adverb to verb)"}]},{"title":"Degree complement with 得 (程度补语)","pattern":"Verb / Adjective + 得 + Degree phrase","explanation":"得 introduces a phrase describing the degree or manner of the verb or adjective. To negate, add 不 before the degree phrase, not before the main verb.","examples":[{"cn":"这道题难得我不会做。","py":"Zhè dào tí nán de wǒ bù huì zuò.","en":"This question is so hard that I can't do it."},{"cn":"他说汉语说得很好。","py":"Tā shuō Hànyǔ shuō de hěn hǎo.","en":"He speaks Chinese very well."},{"cn":"她唱歌唱得不太好。","py":"Tā chàng gē chàng de bù tài hǎo.","en":"She doesn't sing very well."}]},{"title":"越来越 (increasingly)","pattern":"越来越 + Adjective / Verb","explanation":"越来越 expresses that a quality or action is increasing progressively over time. It always precedes the adjective or verb it modifies.","examples":[{"cn":"天气越来越冷了。","py":"Tiānqì yuè lái yuè lěng le.","en":"The weather is getting colder and colder."},{"cn":"他的汉语越来越好。","py":"Tā de Hànyǔ yuè lái yuè hǎo.","en":"His Chinese is getting better and better."},{"cn":"我越来越喜欢北京了。","py":"Wǒ yuè lái yuè xǐhuān Běijīng le.","en":"I like Beijing more and more."}]},{"title":"越…越… (the more…the more…)","pattern":"越 + Verb/Adj + 越 + Verb/Adj","explanation":"This pattern links two conditions proportionally: as one increases, so does the other. Both clauses can share the same subject or have different subjects.","examples":[{"cn":"书越读越有意思。","py":"Shū yuè dú yuè yǒu yìsi.","en":"The more you read the book, the more interesting it becomes."},{"cn":"她越说越快，我越听越不懂。","py":"Tā yuè shuō yuè kuài, wǒ yuè tīng yuè bù dǒng.","en":"The faster she spoke, the less I understood."}]},{"title":"一…就… (as soon as / once…then…)","pattern":"Subject + 一 + Verb1 + (Subject) + 就 + Verb2","explanation":"This pattern expresses that the second action immediately follows or is triggered by the first. Both clauses often share the same subject, but different subjects are also possible.","examples":[{"cn":"我一到家就给你打电话。","py":"Wǒ yī dào jiā jiù gěi nǐ dǎ diànhuà.","en":"As soon as I get home, I'll call you."},{"cn":"他一看电视就睡着了。","py":"Tā yī kàn diànshì jiù shuì zháo le.","en":"He fell asleep as soon as he started watching TV."},{"cn":"一下课，同学们就跑出去玩了。","py":"Yī xià kè, tóngxuémen jiù pǎo chū qù wán le.","en":"As soon as class ended, the students ran out to play."}]},{"title":"虽然…但是… (although…but…)","pattern":"虽然 + Clause1, 但是 / 可是 + Clause2","explanation":"This concessive pattern acknowledges the first clause while introducing a contrasting second clause. 虽然 and 但是 can appear in the same clause or in separate clauses; note that English 'although' and 'but' cannot both appear in the same sentence, but Chinese requires both connectives.","examples":[{"cn":"虽然今天很累，但是我还是去跑步了。","py":"Suīrán jīntiān hěn lèi, dànshì wǒ háishi qù pǎobù le.","en":"Although I was very tired today, I still went running."},{"cn":"虽然他很忙，但是他每天都给父母打电话。","py":"Suīrán tā hěn máng, dànshì tā měitiān dōu gěi fùmǔ dǎ diànhuà.","en":"Although he is very busy, he calls his parents every day."},{"cn":"这件衣服虽然贵，但是质量很好。","py":"Zhè jiàn yīfu suīrán guì, dànshì zhìliàng hěn hǎo.","en":"Although this piece of clothing is expensive, its quality is very good."}]},{"title":"不但…而且… (not only…but also…)","pattern":"不但 + Clause1, 而且 + Clause2","explanation":"This additive pattern escalates from the first clause to the second, indicating both are true. The second clause often contains 还 or 也 for reinforcement.","examples":[{"cn":"他不但会说汉语，而且还会写汉字。","py":"Tā bùdàn huì shuō Hànyǔ, érqiě hái huì xiě Hànzì.","en":"He not only can speak Chinese, but also can write Chinese characters."},{"cn":"这个地方不但很美，而且很安全。","py":"Zhège dìfang bùdàn hěn měi, érqiě hěn ānquán.","en":"This place is not only very beautiful, but also very safe."},{"cn":"她不但学习好，而且很热心帮助同学。","py":"Tā bùdàn xuéxí hǎo, érqiě hěn rèxīn bāngzhù tóngxué.","en":"She not only studies well, but also is very enthusiastic about helping her classmates."}]},{"title":"着 for ongoing state (状态助词)","pattern":"Verb + 着 (+ Object)","explanation":"着 after a verb indicates a continuing state or action that serves as background or accompaniment. It differs from 在 + Verb (active ongoing action) by emphasizing the resultant state rather than the process.","examples":[{"cn":"门开着呢。","py":"Mén kāi zhe ne.","en":"The door is open (and remains so)."},{"cn":"他笑着说了一句话。","py":"Tā xiào zhe shuō le yī jù huà.","en":"He said a sentence with a smile (smilingly)."},{"cn":"她手里拿着一本书。","py":"Tā shǒu lǐ ná zhe yī běn shū.","en":"She is holding a book in her hands."}]},{"title":"是…的 emphasis construction","pattern":"是 + [Time / Place / Manner / Agent] + Verb + 的","explanation":"When an action is already known to have occurred, 是…的 highlights the time, place, manner, or agent of that action. 是 can be omitted in speech, but 的 at the end is essential.","examples":[{"cn":"他是昨天来的。","py":"Tā shì zuótiān lái de.","en":"It was yesterday that he came."},{"cn":"你是在哪里学的汉语？","py":"Nǐ shì zài nǎlǐ xué de Hànyǔ?","en":"Where was it that you learned Chinese?"},{"cn":"这个蛋糕是我妈妈做的。","py":"Zhège dàngāo shì wǒ māma zuò de.","en":"This cake was made by my mother."}]},{"title":"让 / 叫 causative (make/let someone do)","pattern":"Subject + 让/叫 + Person + Verb phrase","explanation":"让 (more polite) and 叫 (more colloquial) both introduce a causative structure meaning 'to make,' 'to let,' or 'to have someone do something.' The person follows immediately, then the action they are made or allowed to perform.","examples":[{"cn":"妈妈让我早点回家。","py":"Māma ràng wǒ zǎo diǎn huí jiā.","en":"Mom told me to come home earlier."},{"cn":"老师叫我们复习第三课。","py":"Lǎoshī jiào wǒmen fùxí dì sān kè.","en":"The teacher told us to review Lesson 3."},{"cn":"他不让我看他的日记。","py":"Tā bù ràng wǒ kàn tā de rìjì.","en":"He won't let me read his diary."}]},{"title":"Verb reduplication (动词重叠)","pattern":"V + V / V一V / V了V (monosyllabic) | VV + VV (disyllabic)","explanation":"Reduplicating a verb softens the request or suggests a brief, casual try at an action. It often implies 'just do it a little' or 'give it a quick try,' making the tone less formal or demanding.","examples":[{"cn":"你看看这张照片。","py":"Nǐ kàn kan zhè zhāng zhàopiàn.","en":"Take a look at this photo."},{"cn":"我们休息一下吧。","py":"Wǒmen xiūxi yīxià ba.","en":"Let's rest for a bit."},{"cn":"你试试这件衣服吧。","py":"Nǐ shì shi zhè jiàn yīfu ba.","en":"Try on this piece of clothing."}]},{"title":"连…都/也… (even…)","pattern":"连 + NP/VP + 都/也 + Verb phrase","explanation":"连…都/也 emphasizes an extreme case: if even this (the least likely or most basic thing) is true, everything else follows. 都 and 也 are interchangeable in this pattern.","examples":[{"cn":"他连饭都没吃就去上班了。","py":"Tā lián fàn dōu méi chī jiù qù shàngbān le.","en":"He went to work without even eating."},{"cn":"这个字连小孩子都会写。","py":"Zhège zì lián xiǎo háizi dōu huì xiě.","en":"Even children can write this character."},{"cn":"我连他的名字也不知道。","py":"Wǒ lián tā de míngzì yě bù zhīdào.","en":"I don't even know his name."}]}],"4":[{"title":"Potential Complement with 得/不 (can/cannot achieve result)","pattern":"Verb + 得/不 + Result/Direction Complement","explanation":"Inserts 得 or 不 between a verb and its result complement to express ability or inability to achieve that result. This differs from 能/不能 + verb, which expresses permission or general capability.","examples":[{"cn":"这道题太难了，我做不出来。","py":"Zhè dào tí tài nán le, wǒ zuò bu chūlái.","en":"This problem is too hard — I can't work it out."},{"cn":"箱子太重，我一个人搬不动。","py":"Xiāngzi tài zhòng, wǒ yī gè rén bān bu dòng.","en":"The suitcase is too heavy; I can't move it alone."},{"cn":"别担心，这个任务我们完成得了。","py":"Bié dāngxīn, zhège rènwù wǒmen wánchéng de liǎo.","en":"Don't worry, we can finish this task."}]},{"title":"Degree Complement with 得 (how well / to what extent)","pattern":"Verb/Adj + 得 + Complement Phrase","explanation":"The syllable 得 introduces a phrase describing the degree or manner of an action or state. The complement can be a simple adjective, a complex clause, or even a subject-predicate structure.","examples":[{"cn":"她汉语说得非常流利。","py":"Tā Hànyǔ shuō de fēicháng liúlì.","en":"She speaks Chinese very fluently."},{"cn":"他跑得我都追不上。","py":"Tā pǎo de wǒ dōu zhuī bu shàng.","en":"He ran so fast that I couldn't catch up."},{"cn":"昨晚她兴奋得睡不着觉。","py":"Zuó wǎn tā xīngfèn de shuì bu zháo jiào.","en":"Last night she was so excited she couldn't sleep."}]},{"title":"Progressive action with 着…呢 (ongoing state)","pattern":"Subject + Verb + 着 + (Object) + 呢","explanation":"Combines the aspect marker 着 (which marks a continuing state) with sentence-final 呢 to emphasize that an action or state is currently in progress. It is more emphatic than 着 alone.","examples":[{"cn":"门开着呢，进来吧。","py":"Mén kāi zhe ne, jìnlái ba.","en":"The door is open — come on in."},{"cn":"他们还在会议室里谈着呢。","py":"Tāmen hái zài huìyì shì lǐ tán zhe ne.","en":"They are still talking in the meeting room."},{"cn":"孩子们在外面玩着呢，别叫他们。","py":"Háizimen zài wàimiàn wán zhe ne, bié jiào tāmen.","en":"The kids are playing outside — don't call them."}]},{"title":"Contrast: 不是…而是 (not X but rather Y)","pattern":"不是 + A，而是 + B","explanation":"Negates the first element and asserts the second as the true fact. Both A and B must be parallel in grammatical structure (both nouns, both verb phrases, etc.).","examples":[{"cn":"他迟到不是因为懒，而是因为堵车。","py":"Tā chídào bù shì yīnwèi lǎn, ér shì yīnwèi dǔchē.","en":"He was late not because he was lazy, but because of traffic."},{"cn":"这件事不是你的错，而是我没说清楚。","py":"Zhè jiàn shì bù shì nǐ de cuò, ér shì wǒ méi shuō qīngchǔ.","en":"This isn't your fault — rather, I didn't explain it clearly."},{"cn":"我需要的不是钱，而是你的支持。","py":"Wǒ xūyào de bù shì qián, ér shì nǐ de zhīchí.","en":"What I need is not money but your support."}]},{"title":"Logical consequence: 既然…就 (since / now that … then)","pattern":"既然 + Established Fact，Subject + 就 + Conclusion","explanation":"Presents a fact that is already accepted by both parties and draws a logical conclusion from it. The premise in 既然 is always something the listener already knows or has admitted.","examples":[{"cn":"既然你已经决定了，就不要后悔。","py":"Jìrán nǐ yǐjīng juédìng le, jiù bú yào hòuhuǐ.","en":"Since you've already decided, don't have regrets."},{"cn":"既然天气这么好，我们就出去走走吧。","py":"Jìrán tiānqì zhème hǎo, wǒmen jiù chūqù zǒuzou ba.","en":"Since the weather is so nice, let's go for a walk."},{"cn":"既然你不喜欢这份工作，就应该换一个。","py":"Jìrán nǐ bù xǐhuan zhè fèn gōngzuò, jiù yīnggāi huàn yī gè.","en":"Since you don't like this job, you should change it."}]},{"title":"Concession: 即使…也 (even if … still)","pattern":"即使 + Hypothetical Condition，Subject + 也 + Result","explanation":"Concedes an extreme or unlikely condition while asserting that the outcome remains unchanged. 即使 is stronger and more formal than 就算; the condition is often counterfactual.","examples":[{"cn":"即使下雨，比赛也不会取消。","py":"Jíshǐ xià yǔ, bǐsài yě bú huì qǔxiāo.","en":"Even if it rains, the match will not be cancelled."},{"cn":"即使再累，他也坚持跑完全程。","py":"Jíshǐ zài lèi, tā yě jiānchí pǎo wán quánchéng.","en":"No matter how tired he was, he still persisted to finish the whole race."},{"cn":"即使你不同意，我们也要按计划进行。","py":"Jíshǐ nǐ bù tóngyì, wǒmen yě yào àn jìhuà jìnxíng.","en":"Even if you disagree, we will proceed according to plan."}]},{"title":"Universal condition: 无论…都 (no matter … always)","pattern":"无论 + Question Word / A还是B，Subject + 都 + Result","explanation":"States that the result holds true under every possible condition. The 无论 clause must contain a question word (什么、谁、怎么, etc.) or an A还是B alternative; 都 in the main clause is obligatory.","examples":[{"cn":"无论遇到什么困难，他都不放弃。","py":"Wúlùn yùdào shénme kùnnán, tā dōu bú fàngqì.","en":"No matter what difficulties he encounters, he never gives up."},{"cn":"无论你去不去，我都会去。","py":"Wúlùn nǐ qù bu qù, wǒ dōu huì qù.","en":"Regardless of whether you go, I will go."},{"cn":"无论多忙，她都坚持锻炼。","py":"Wúlùn duō máng, tā dōu jiānchí duànliàn.","en":"No matter how busy she is, she keeps exercising."}]},{"title":"Sufficient condition: 只要…就 (as long as … then)","pattern":"只要 + Sufficient Condition，Subject + 就 + Result","explanation":"States that the condition in 只要 is all that is required for the result. Contrast with 只有…才, which requires a necessary (not just sufficient) condition.","examples":[{"cn":"只要你努力，就一定能成功。","py":"Zhǐyào nǐ nǔlì, jiù yīdìng néng chénggōng.","en":"As long as you work hard, you will definitely succeed."},{"cn":"只要天气好，我们就去爬山。","py":"Zhǐyào tiānqì hǎo, wǒmen jiù qù páshān.","en":"As long as the weather is good, we'll go hiking."},{"cn":"只要提前预约，就可以免费参观。","py":"Zhǐyào tíqián yùyuē, jiù kěyǐ miǎnfèi cānguān.","en":"As long as you book in advance, you can visit for free."}]},{"title":"Necessary condition: 只有…才 (only if … then / only then)","pattern":"只有 + Necessary Condition，Subject + 才 + Result","explanation":"States that the condition is the one and only way the result can happen — it is necessary, not merely sufficient. Removing the condition means the result cannot occur.","examples":[{"cn":"只有坚持练习，才能把汉语说好。","py":"Zhǐyǒu jiānchí liànxí, cái néng bǎ Hànyǔ shuō hǎo.","en":"Only by persisting in practice can you speak Chinese well."},{"cn":"只有亲身经历，你才能真正理解。","py":"Zhǐyǒu qīnshēn jīnglì, nǐ cái néng zhēnzhèng lǐjiě.","en":"Only through personal experience can you truly understand."},{"cn":"只有凭有效证件，才能进入这栋楼。","py":"Zhǐyǒu píng yǒuxiào zhèngjiàn, cái néng jìnrù zhè dòng lóu.","en":"Only with a valid ID can you enter this building."}]},{"title":"Emphatic inclusion: 连…都/也 (even … also/even)","pattern":"连 + NP/VP，Subject + 都/也 + Verb","explanation":"Highlights an extreme or unexpected member of a set to imply that everything else in that set is equally or more so. 连 fronts the emphasized element; 都 or 也 appears before the main verb.","examples":[{"cn":"这道菜连小孩子都会做。","py":"Zhè dào cài lián xiǎo háizi dōu huì zuò.","en":"Even a small child can cook this dish."},{"cn":"他太累了，连饭都没吃就睡着了。","py":"Tā tài lèi le, lián fàn dōu méi chī jiù shuìzháo le.","en":"He was so tired that he fell asleep without even eating."},{"cn":"她连自己的生日都忘了。","py":"Tā lián zìjǐ de shēngrì dōu wàng le.","en":"She even forgot her own birthday."}]},{"title":"Perspective marker: 对…来说 (from the perspective of / for)","pattern":"对 + NP + 来说，…","explanation":"Frames the following statement as being true or relevant from a particular person's or group's point of view. It differs from 对…有 (have an effect on) and 对于 (concerning), though they often overlap.","examples":[{"cn":"对我来说，健康比金钱更重要。","py":"Duì wǒ lái shuō, jiànkāng bǐ jīnqián gèng zhòngyào.","en":"For me, health is more important than money."},{"cn":"对初学者来说，这本书有点难。","py":"Duì chūxuézhě lái shuō, zhè běn shū yǒudiǎn nán.","en":"For beginners, this book is a bit difficult."},{"cn":"对他们公司来说，这个合同非常关键。","py":"Duì tāmen gōngsī lái shuō, zhège hétong fēicháng guānjiàn.","en":"For their company, this contract is extremely important."}]},{"title":"Topic marker: 关于 (regarding / about / concerning)","pattern":"关于 + Topic，Subject + Predicate","explanation":"Introduces the topic of discussion. When 关于 appears at the start of a sentence before the subject, it is a topic frame; when it follows a verb, it is a prepositional phrase. It does not indicate personal perspective (use 对…来说 for that).","examples":[{"cn":"关于这个问题，我们需要进一步讨论。","py":"Guānyú zhège wèntí, wǒmen xūyào jìnyībù tǎolùn.","en":"Regarding this issue, we need to discuss it further."},{"cn":"他写了一篇关于环境保护的文章。","py":"Tā xiě le yī piān guānyú huánjìng bǎohù de wénzhāng.","en":"He wrote an article about environmental protection."},{"cn":"关于明天的计划，大家有什么意见？","py":"Guānyú míngtiān de jìhuà, dàjiā yǒu shénme yìjiàn?","en":"Regarding tomorrow's plan, does anyone have any opinions?"}]},{"title":"Cause marker: 由于 (due to / owing to)","pattern":"由于 + Cause，Subject + Result/Outcome","explanation":"A slightly formal conjunction or preposition introducing a cause, often used in written or semiformal speech. It typically states objective causes; for expressing personal reasons, 因为 is more common.","examples":[{"cn":"由于天气原因，航班被推迟了。","py":"Yóuyú tiānqì yuányīn, hángbān bèi tuīchí le.","en":"Due to weather conditions, the flight was delayed."},{"cn":"由于准备不足，他在考试中失败了。","py":"Yóuyú zhǔnbèi bùzú, tā zài kǎoshì zhōng shībài le.","en":"Owing to insufficient preparation, he failed the exam."},{"cn":"由于双方达成了协议，合作顺利开始。","py":"Yóuyú shuāngfāng dáchéng le xiéyì, hézuò shùnlì kāishǐ.","en":"Because both sides reached an agreement, the cooperation started smoothly."}]},{"title":"Means/channel marker: 通过 (through / by means of / via)","pattern":"通过 + Means/Channel，Subject + Achieves Goal","explanation":"Indicates the method, channel, or intermediary through which something is accomplished. It can be a preposition (before the subject) or a verb (meaning 'to pass through / to approve').","examples":[{"cn":"通过不断练习，他的口语进步很快。","py":"Tōngguò bùduàn liànxí, tā de kǒuyǔ jìnbù hěn kuài.","en":"Through constant practice, his spoken language improved rapidly."},{"cn":"我是通过朋友介绍认识她的。","py":"Wǒ shì tōngguò péngyou jièshào rènshi tā de.","en":"I got to know her through a friend's introduction."},{"cn":"他们通过网络了解到了最新消息。","py":"Tāmen tōngguò wǎngluò liǎojiě dào le zuìxīn xiāoxi.","en":"They found out the latest news through the internet."}]},{"title":"Exemplification: 拿…来说 (take … as an example)","pattern":"拿 + Example + 来说，…","explanation":"A spoken-style phrase that introduces a concrete example to support a general point. It is more colloquial than 以…为例 and is commonly used in conversation and informal writing.","examples":[{"cn":"拿中国来说，这几年经济发展很快。","py":"Ná Zhōngguó lái shuō, zhè jǐ nián jīngjì fāzhǎn hěn kuài.","en":"Take China as an example — its economy has grown very fast in recent years."},{"cn":"拿学汉语来说，坚持是最重要的。","py":"Ná xué Hànyǔ lái shuō, jiānchí shì zuì zhòngyào de.","en":"Take learning Chinese as an example — perseverance is the most important thing."},{"cn":"拿我们公司来说，员工福利一直在提高。","py":"Ná wǒmen gōngsī lái shuō, yuángōng fúlì yīzhí zài tígāo.","en":"Take our company for example — employee benefits have been improving all along."}]},{"title":"Otherwise / or else: 否则 (otherwise / or else)","pattern":"Statement，否则 + Negative Consequence","explanation":"A conjunction linking a statement to the negative outcome that would occur if it were not heeded. It is more formal than 要不然 and typically appears in the second clause.","examples":[{"cn":"你得快点儿，否则会迟到。","py":"Nǐ děi kuài diǎnr, fǒuzé huì chídào.","en":"You need to hurry, otherwise you'll be late."},{"cn":"请关好窗户，否则雨水会进来。","py":"Qǐng guān hǎo chuānghù, fǒuzé yǔshuǐ huì jìnlái.","en":"Please close the windows, or rainwater will get in."},{"cn":"要认真复习，否则考试很难通过。","py":"Yào rènzhēn fùxí, fǒuzé kǎoshì hěn nán tōngguò.","en":"You must review seriously, or it will be very hard to pass the exam."}]},{"title":"Causal explanation: 之所以…是因为 (the reason … is because)","pattern":"Subject + 之所以 + VP，是因为 + Reason","explanation":"A formal construction that front-focuses the result or known fact and then explains its cause. The 之所以 clause states what happened; 是因为 gives the reason. It is the mirror image of 因为…所以.","examples":[{"cn":"他之所以成功，是因为他从不放弃。","py":"Tā zhī suǒyǐ chénggōng, shì yīnwèi tā cóng bù fàngqì.","en":"The reason he succeeded is that he never gave up."},{"cn":"我之所以喜欢北京，是因为这里文化丰富。","py":"Wǒ zhī suǒyǐ xǐhuan Běijīng, shì yīnwèi zhèlǐ wénhuà fēngfù.","en":"The reason I love Beijing is that the culture here is so rich."},{"cn":"她之所以没来，是因为临时有事。","py":"Tā zhī suǒyǐ méi lái, shì yīnwèi línshí yǒu shì.","en":"The reason she didn't come is that something came up at the last minute."}]},{"title":"Passive with 被 (extended / adversarial passive)","pattern":"Subject + 被 + Agent + Verb + Result Complement/了","explanation":"At HSK 4 the 被 passive is extended: the agent is usually present, and the verb must carry a result complement, aspect marker, or other element — a bare verb after 被 is ungrammatical. It typically carries an adversarial or undesirable connotation.","examples":[{"cn":"我的钱包被小偷偷走了。","py":"Wǒ de qiánbāo bèi xiǎotōu tōu zǒu le.","en":"My wallet was stolen by a pickpocket."},{"cn":"那篇文章被编辑大幅修改了。","py":"Nà piān wénzhāng bèi biānjí dàfú xiūgǎi le.","en":"That article was extensively revised by the editor."},{"cn":"他的建议被大家接受了。","py":"Tā de jiànyì bèi dàjiā jiēshòu le.","en":"His suggestion was accepted by everyone."}]}],"5":[{"title":"不仅…还/而且 (not only … but also, elevated)","pattern":"不仅 + [clause A]，还/而且 + [clause B]","explanation":"A formal upgrade of 也 for additive escalation, often in written or semi-formal registers. The second clause intensifies or expands on the first; use 而且 when the subjects differ.","examples":[{"cn":"这项政策不仅降低了成本，还提高了效率。","py":"Zhè xiàng zhèngcè bùjǐn jiàngdīle chéngběn, hái tígāole xiàolǜ.","en":"This policy not only reduced costs but also improved efficiency."},{"cn":"他不仅会说汉语，而且写得非常漂亮。","py":"Tā bùjǐn huì shuō Hànyǔ, érqiě xiě de fēicháng piàoliang.","en":"He can not only speak Chinese but also writes it beautifully."},{"cn":"这次失败不仅没有打倒她，还让她变得更坚强。","py":"Zhè cì shībài bùjǐn méiyǒu dǎdǎo tā, hái ràng tā biàn de gèng jiānqiáng.","en":"This failure not only didn't defeat her but actually made her stronger."}]},{"title":"不仅…反而 (not only not … but on the contrary)","pattern":"不仅没有 + [expected result]，反而 + [contrary result]","explanation":"Highlights a result opposite to what was expected. 反而 signals a reversal and carries a tone of surprise or irony; it cannot be replaced by 还.","examples":[{"cn":"吃了药之后，他的病不仅没有好转，反而更严重了。","py":"Chīle yào zhīhòu, tā de bìng bùjǐn méiyǒu hǎozhuǎn, fǎn'ér gèng yánzhòng le.","en":"After taking the medicine, his illness not only didn't improve but got even worse."},{"cn":"批评他反而让他更加骄傲了。","py":"Pīpíng tā fǎn'ér ràng tā gèngjiā jiāo'ào le.","en":"Criticizing him on the contrary made him even more arrogant."},{"cn":"降价之后，销量不仅没有增加，反而下降了。","py":"Jiàngjià zhīhòu, xiāoliàng bùjǐn méiyǒu zēngjiā, fǎn'ér xiàjiàng le.","en":"After the price cut, sales not only didn't increase but actually fell."}]},{"title":"与其…不如 (rather than … it's better to)","pattern":"与其 + [less preferred action]，不如 + [preferred action]","explanation":"Expresses a preference by rejecting one option in favor of another. Both clauses share the same subject; the subject usually comes before 与其 if stated.","examples":[{"cn":"与其抱怨现状，不如努力改变它。","py":"Yǔqí bàoyuàn xiànzhuàng, bùrú nǔlì gǎibiàn tā.","en":"Rather than complaining about the situation, it's better to work hard to change it."},{"cn":"与其等待机会，不如主动创造机会。","py":"Yǔqí děngdài jīhuì, bùrú zhǔdòng chuàngzào jīhuì.","en":"Rather than waiting for opportunities, it's better to actively create them."},{"cn":"与其买一件便宜的，不如多存钱买一件好的。","py":"Yǔqí mǎi yī jiàn piányí de, bùrú duō cún qián mǎi yī jiàn hǎo de.","en":"Rather than buying a cheap one, it's better to save up and buy a good one."}]},{"title":"宁可…也 (would rather … than)","pattern":"宁可 + [sacrifice/cost]，也 + [insistence]","explanation":"States a firm willingness to accept a hardship in order to uphold a principle or goal. The 也 clause expresses what the speaker insists on doing despite the cost.","examples":[{"cn":"他宁可失去工作，也不愿意出卖朋友。","py":"Tā nìngkě shīqù gōngzuò, yě bù yuànyì chūmài péngyou.","en":"He would rather lose his job than betray his friends."},{"cn":"我宁可早起两小时，也要把报告做好。","py":"Wǒ nìngkě zǎoqǐ liǎng xiǎoshí, yě yào bǎ bàogào zuòhǎo.","en":"I would rather get up two hours early than not do the report well."},{"cn":"她宁可一个人住，也不想和难相处的室友同住。","py":"Tā nìngkě yīgè rén zhù, yě bù xiǎng hé nán xiāngchǔ de shìyǒu tóng zhù.","en":"She would rather live alone than share with a difficult roommate."}]},{"title":"一方面…另一方面 (on one hand … on the other hand)","pattern":"一方面 + [perspective A]，另一方面 + [perspective B]","explanation":"Presents two coexisting aspects, reasons, or considerations simultaneously. Common in analytical writing and formal speech.","examples":[{"cn":"发展旅游业，一方面能增加收入，另一方面可能破坏环境。","py":"Fāzhǎn lǚyóuyè, yīfāngmiàn néng zēngjiā shōurù, lìng yī fāngmiàn kěnéng pòhuài huánjìng.","en":"Developing tourism can on one hand increase income and on the other hand may damage the environment."},{"cn":"他一方面很想去，另一方面又担心花太多钱。","py":"Tā yīfāngmiàn hěn xiǎng qù, lìng yī fāngmiàn yòu dānxīn huā tài duō qián.","en":"On one hand he really wants to go; on the other hand he worries about spending too much money."},{"cn":"这个决定，一方面体现了公司的诚意，另一方面也是市场竞争的需要。","py":"Zhège juédìng, yīfāngmiàn tǐxiàn le gōngsī de chéngyì, lìng yī fāngmiàn yě shì shìchǎng jìngzhēng de xūyào.","en":"This decision on one hand shows the company's sincerity and on the other is a requirement of market competition."}]},{"title":"凡是…都 (whatever / whoever … all)","pattern":"凡是 + [universal subject/condition]，都 + [result/predicate]","explanation":"Makes a sweeping universal statement covering every member of a category. 凡是 is more formal than 所有 and is typical of regulations, instructions, and written rules.","examples":[{"cn":"凡是参加比赛的选手，都必须提前注册。","py":"Fánshì cānjiā bǐsài de xuǎnshǒu, dōu bìxū tíqián zhùcè.","en":"All contestants who participate in the competition must register in advance."},{"cn":"凡是努力过的人，都不会后悔。","py":"Fánshì nǔlì guò de rén, dōu bù huì hòuhuǐ.","en":"Anyone who has worked hard will have no regrets."},{"cn":"凡是违反规定的行为，都将受到处罚。","py":"Fánshì wéifǎn guīdìng de xíngwéi, dōu jiāng shòudào chǔfá.","en":"Any behavior that violates the regulations will be punished."}]},{"title":"鉴于 (in view of / given that)","pattern":"鉴于 + [reason/situation]，[conclusion/decision]","explanation":"A formal written connector introducing a factual basis for a decision or conclusion. Equivalent to 'in view of' or 'given'; rarely used in spoken Chinese.","examples":[{"cn":"鉴于目前的经济形势，公司决定暂停招聘。","py":"Jiànyú mùqián de jīngjì xíngshì, gōngsī juédìng zànting zhāopìn.","en":"In view of the current economic situation, the company has decided to suspend hiring."},{"cn":"鉴于他的突出贡献，董事会决定给予特别奖励。","py":"Jiànyú tā de tūchū gòngxiàn, dǒngshìhuì juédìng jǐyǔ tèbié jiǎnglì.","en":"Given his outstanding contributions, the board of directors decided to award him a special bonus."},{"cn":"鉴于双方意见分歧较大，会议决定延期举行。","py":"Jiànyú shuāngfāng yìjiàn fēnqí jiào dà, huìyì juédìng yánqī jǔxíng.","en":"Given the significant divergence of opinions between the two parties, the meeting was postponed."}]},{"title":"以…为 (to take … as / to use … as)","pattern":"以 + [noun/concept] + 为 + [role/standard/basis]","explanation":"A formal, often written, structure indicating what something is based on, oriented toward, or used as. Common in academic, policy, and descriptive contexts.","examples":[{"cn":"这所大学以培养创新人才为目标。","py":"Zhè suǒ dàxué yǐ péiyǎng chuàngxīn réncái wéi mùbiāo.","en":"This university takes cultivating innovative talent as its goal."},{"cn":"他以诚实守信为做人的基本原则。","py":"Tā yǐ chénshí shǒuxìn wéi zuòrén de jīběn yuánzé.","en":"He takes honesty and integrity as the basic principles of conduct."},{"cn":"公司以客户满意度为衡量服务质量的标准。","py":"Gōngsī yǐ kèhù mǎnyìdù wéi héngliáng fúwù zhìliàng de biāozhǔn.","en":"The company uses customer satisfaction as the standard for measuring service quality."}]},{"title":"难道…吗 (could it really be that … ?)","pattern":"难道 + [rhetorical statement] + 吗/不成","explanation":"Forms a rhetorical question implying the answer is obviously 'no' (or 'yes'). 难道 intensifies disbelief or indignation; the expected answer is the opposite of what is stated.","examples":[{"cn":"难道你真的认为靠运气就能成功吗？","py":"Nándào nǐ zhēn de rènwéi kào yùnqi jiù néng chénggōng ma?","en":"Could you really think that you can succeed by relying on luck alone?"},{"cn":"他这么聪明，难道连这道题都不会做吗？","py":"Tā zhème cōngming, nándào lián zhè dào tí dōu bù huì zuò ma?","en":"He is so smart — could he really not know how to solve this problem?"},{"cn":"难道我们就这样放弃了吗？","py":"Nándào wǒmen jiù zhèyàng fàngqì le ma?","en":"Are we really just going to give up like this?"}]},{"title":"不至于 (not to the extent of / it won't go so far as)","pattern":"[subject] + 不至于 + [excessive/extreme outcome]","explanation":"Asserts that a situation will not reach an extreme or undesirable degree. It is used to reassure or push back against an exaggerated concern.","examples":[{"cn":"事情不至于像你说的那么糟糕吧？","py":"Shìqing bù zhìyú xiàng nǐ shuō de nàme zāogāo ba?","en":"Surely things won't be as bad as you say?"},{"cn":"他只是有点累，不至于生病的。","py":"Tā zhǐshì yǒudiǎn lèi, bù zhìyú shēngbìng de.","en":"He's just a bit tired; it won't go so far as him getting sick."},{"cn":"一次小小的失误不至于影响你整个职业生涯。","py":"Yī cì xiǎoxiǎo de shīwù bù zhìyú yǐngxiǎng nǐ zhěnggè zhíyè shēngyá.","en":"A small mistake won't go so far as to affect your entire career."}]},{"title":"何况 (let alone / not to mention / all the more so)","pattern":"[prior statement]，何况 + [stronger/more extreme case]","explanation":"Introduces a case that, given the prior statement, is even more obvious or significant. It can reinforce either a positive or negative argument by escalating to a stronger example.","examples":[{"cn":"连专家都觉得这道题难，何况普通学生呢？","py":"Lián zhuānjiā dōu juéde zhè dào tí nán, hékuàng pǔtōng xuésheng ne?","en":"Even experts find this question difficult, let alone ordinary students."},{"cn":"他连母语都说不好，何况外语。","py":"Tā lián mǔyǔ dōu shuō bù hǎo, hékuàng wàiyǔ.","en":"He can't even speak his native language well, let alone a foreign one."},{"cn":"短短一个月都能学会，何况给你三个月呢？","py":"Duǎnduǎn yī gè yuè dōu néng xuéhuì, hékuàng gěi nǐ sān gè yuè ne?","en":"You can learn it in just one month, let alone with three months to spare."}]},{"title":"总之 (in short / in a word / to sum up)","pattern":"总之，+ [summary conclusion]","explanation":"Introduces a concluding summary statement after listing reasons or arguments. It signals that what follows encapsulates everything said before; common in both spoken and written Chinese.","examples":[{"cn":"无论原因是什么，总之结果让人失望。","py":"Wúlùn yuányīn shì shénme, zǒngzhī jiéguǒ ràng rén shīwàng.","en":"Whatever the reasons may be, in short the result is disappointing."},{"cn":"他经验丰富，能力突出，总之是个非常合适的候选人。","py":"Tā jīngyàn fēngfù, nénglì tūchū, zǒngzhī shì gè fēicháng héshì de hòuxuǎnrén.","en":"He is experienced, capable, and outstanding — in a word, a very suitable candidate."},{"cn":"总之，这次合作对双方都有利。","py":"Zǒngzhī, zhè cì hézuò duì shuāngfāng dōu yǒulì.","en":"In short, this collaboration is beneficial to both parties."}]},{"title":"以便 / 以免 (so as to / so as to avoid)","pattern":"[main action] + 以便/以免 + [purpose/avoided outcome]","explanation":"以便 introduces a positive purpose ('so as to enable'), while 以免 introduces a negative one ('so as to avoid'). Both are formal and primarily written; the subjects of both clauses are usually the same.","examples":[{"cn":"请提前确认时间，以便我们做好准备。","py":"Qǐng tíqián quèrèn shíjiān, yǐbiàn wǒmen zuòhǎo zhǔnbèi.","en":"Please confirm the time in advance so that we can prepare."},{"cn":"出门前检查一下煤气，以免发生危险。","py":"Chūmén qián jiǎnchá yīxià méiqì, yǐmiǎn fāshēng wēixiǎn.","en":"Check the gas before going out so as to avoid any danger."},{"cn":"把重要文件备份，以免丢失。","py":"Bǎ zhòngyào wénjiàn bèifèn, yǐmiǎn diūshī.","en":"Back up important documents so as to avoid losing them."}]},{"title":"简直 (simply / absolutely / it's just like)","pattern":"简直 + [hyperbolic predicate / 像…一样]","explanation":"An intensifying adverb conveying that something is so extreme it almost defies belief, often used for emphasis or hyperbole. It frequently co-occurs with 像…一样 to draw a strong comparison.","examples":[{"cn":"这部电影简直太精彩了，我看了三遍。","py":"Zhè bù diànyǐng jiǎnzhí tài jīngcǎi le, wǒ kàn le sān biàn.","en":"This film is simply amazing — I've watched it three times."},{"cn":"他学中文的速度简直令人难以置信。","py":"Tā xué Zhōngwén de sùdù jiǎnzhí lìng rén nányǐ zhìxìn.","en":"The speed at which he learns Chinese is simply unbelievable."},{"cn":"这两个人简直像是亲兄弟一样。","py":"Zhè liǎng gè rén jiǎnzhí xiàng shì qīn xiōngdì yīyàng.","en":"These two people are simply like real brothers."}]},{"title":"未必 (not necessarily / may not)","pattern":"[subject] + 未必 + [assumed predicate]","explanation":"Negates certainty without asserting the opposite; it means 'it is not necessarily the case that.' More formal and nuanced than 不一定, and common in written argumentation.","examples":[{"cn":"贵的东西未必就是好的。","py":"Guì de dōngxi wèibì jiù shì hǎo de.","en":"Expensive things are not necessarily good."},{"cn":"成绩好未必代表能力强。","py":"Chéngjì hǎo wèibì dàibiǎo nénglì qiáng.","en":"Good grades do not necessarily mean high ability."},{"cn":"他未必知道这件事的真相。","py":"Tā wèibì zhīdào zhè jiàn shì de zhēnxiàng.","en":"He may not necessarily know the truth about this matter."}]},{"title":"把 + result/direction complement (extended)","pattern":"把 + [object] + [verb] + [result complement / directional complement]","explanation":"At HSK 5 the 把 construction extends to complex result complements showing transformation, disposal, or thorough completion — e.g. 把…写满, 把…搞清楚, 把…翻译成. The object must be specific and definite.","examples":[{"cn":"请把这份合同翻译成英文。","py":"Qǐng bǎ zhè fèn hétong fānyì chéng Yīngwén.","en":"Please translate this contract into English."},{"cn":"他把问题彻底搞清楚了才离开。","py":"Tā bǎ wèntí chèdǐ gǎo qīngchǔ le cái líkāi.","en":"He didn't leave until he had thoroughly figured out the problem."},{"cn":"她把整本笔记本写满了公式。","py":"Tā bǎ zhěng běn bǐjìběn xiě mǎn le gōngshì.","en":"She filled the entire notebook with formulas."}]}],"6":[{"title":"固然…但/却 (Concession: 'Granted… but')","pattern":"固然 [acknowledged fact]，但/却 [contrasting point]","explanation":"Used in formal writing to concede a point before introducing a stronger counterargument. More literary than 虽然…但是 and signals a sophisticated rhetorical turn.","examples":[{"cn":"这项计划固然有其优点，但实施起来困难重重。","py":"Zhè xiàng jìhuà gùrán yǒu qí yōudiǎn, dàn shíshī qǐlái kùnnan chóngchóng.","en":"Granted, this plan has its merits, but implementing it is fraught with difficulties."},{"cn":"金钱固然重要，却并非幸福的全部。","py":"Jīnqián gùrán zhòngyào, què bìngfēi xìngfú de quánbù.","en":"Money is certainly important, yet it is by no means the whole of happiness."},{"cn":"他固然才华横溢，但缺乏实际经验。","py":"Tā gùrán cáihuá héng yì, dàn quēfá shíjì jīngyàn.","en":"He is undeniably talented, but he lacks practical experience."}]},{"title":"一来…二来 (Dual-reason enumeration)","pattern":"一来 [reason 1]，二来 [reason 2]","explanation":"Lists two parallel reasons or purposes for an action, common in formal spoken and written Chinese. Can extend to 三来 for a third reason.","examples":[{"cn":"他选择留在国内，一来可以照顾父母，二来便于开展业务。","py":"Tā xuǎnzé liú zài guónèi, yī lái kěyǐ zhàogù fùmǔ, èr lái biànyú kāizhǎn yèwù.","en":"He chose to stay in the country: for one thing, he could care for his parents; for another, it was convenient for running his business."},{"cn":"多读书一来能增长知识，二来能陶冶情操。","py":"Duō dú shū yī lái néng zēngzhǎng zhīshi, èr lái néng táoyě qíngcāo.","en":"Reading more, firstly, expands one's knowledge; secondly, it cultivates one's character."}]},{"title":"与此同时 (Simultaneity: 'At the same time')","pattern":"[clause 1]。与此同时，[clause 2]","explanation":"A formal written connector indicating two events or processes happening concurrently. Primarily a sentence-level adverbial, not used within a single clause like 同时 can be.","examples":[{"cn":"经济持续增长。与此同时，环境问题也日益突出。","py":"Jīngjì chíxù zēngzhǎng. Yǔ cǐ tóngshí, huánjìng wèntí yě rìyì tūchū.","en":"The economy continues to grow. At the same time, environmental issues are becoming increasingly prominent."},{"cn":"政府加大了教育投入，与此同时也强化了职业培训体系。","py":"Zhèngfǔ jiādàle jiàoyù tóurù, yǔ cǐ tóngshí yě qiánghuàle zhíyè péixùn tǐxì.","en":"The government increased investment in education; at the same time, it also strengthened the vocational training system."}]},{"title":"倘若/假如…便 (Formal Conditional: 'If… then')","pattern":"倘若/假如 [condition]，便 [consequence]","explanation":"A formal written conditional pair. 倘若 and 假如 are more literary alternatives to 如果, while 便 is a more elegant written substitute for 就.","examples":[{"cn":"倘若此事属实，便需立即采取措施。","py":"Tǎngruò cǐ shì shǔ shí, biàn xū lìjí cǎiqǔ cuòshī.","en":"If this matter is true, then measures must be taken immediately."},{"cn":"假如你愿意合作，便可共享研究成果。","py":"Jiǎrú nǐ yuànyì hézuò, biàn kě gòngxiǎng yánjiū chéngguǒ.","en":"If you are willing to cooperate, then you may share in the research results."},{"cn":"倘若缺乏资金，项目便难以为继。","py":"Tǎngruò quēfá zījīn, xiàngmù biàn nányǐ wéijì.","en":"If funding is lacking, the project will be difficult to sustain."}]},{"title":"即便如此 (Concessive: 'Even so / Even if that is the case')","pattern":"即便如此，[clause showing persistence or qualification]","explanation":"A formal discourse marker that acknowledges a preceding point while asserting that the following statement still holds. It functions as an emphatic 'even so' at the start of a sentence.","examples":[{"cn":"这条路充满艰险，即便如此，他也毫无退意。","py":"Zhè tiáo lù chōngmǎn jiān xiǎn, jíbiàn rúcǐ, tā yě háowú tuì yì.","en":"This path is full of dangers; even so, he had no intention of retreating."},{"cn":"结果或许令人失望，即便如此，我们也要坚持到底。","py":"Jiéguǒ huòxǔ lìng rén shīwàng, jíbiàn rúcǐ, wǒmen yě yào jiānchí dàodǐ.","en":"The result may be disappointing; even so, we must persevere to the end."}]},{"title":"唯有…才 (Exclusive Condition: 'Only by… can')","pattern":"唯有 [condition/means]，才能 [result]","explanation":"A formal emphatic structure asserting that the stated condition is the sole path to the result. More literary and stronger in exclusivity than 只有…才.","examples":[{"cn":"唯有坚持不懈，才能实现梦想。","py":"Wéiyǒu jiānchí bùxiè, cái néng shíxiàn mèngxiǎng.","en":"Only by persevering without cease can one realize one's dreams."},{"cn":"唯有各方通力合作，才能解决这一全球性难题。","py":"Wéiyǒu gèfāng tōnglì hézuò, cái néng jiějué zhè yī quánqiúxìng nántí.","en":"Only through the concerted cooperation of all parties can this global challenge be resolved."},{"cn":"唯有深入基层，才能了解真实的民情。","py":"Wéiyǒu shēnrù jīcéng, cái néng liǎojiě zhēnshí de mínqíng.","en":"Only by going deep into the grassroots level can one understand the true conditions of the people."}]},{"title":"凭借 (Means/Basis: 'By virtue of / Relying on')","pattern":"凭借 [resource/quality/means]，[achievement or action]","explanation":"A formal preposition meaning 'by dint of' or 'relying on'. It highlights the specific asset or means that enables an outcome, with a more formal register than 靠.","examples":[{"cn":"他凭借多年的经验，迅速找到了问题所在。","py":"Tā píngjiè duō nián de jīngyàn, xùnsù zhǎodàole wèntí suǒzài.","en":"Drawing on his years of experience, he quickly identified the source of the problem."},{"cn":"该公司凭借技术创新在行业中脱颖而出。","py":"Gāi gōngsī píngjiè jìshù chuàngxīn zài hángyè zhōng tuōyǐng ér chū.","en":"The company stood out in the industry by virtue of technological innovation."},{"cn":"凭借坚定的意志，她克服了重重困难。","py":"Píngjiè jiāndìng de yìzhì, tā kèfúle chóngchóng kùnnan.","en":"By virtue of her firm willpower, she overcame one difficulty after another."}]},{"title":"致使 (Causation: 'Causing / Leading to' — negative result)","pattern":"[cause/action]，致使 [negative consequence]","explanation":"A formal written verb meaning 'to cause' or 'to result in', almost exclusively used before negative outcomes. It is stronger and more formal than 导致 and implies direct responsibility.","examples":[{"cn":"管理层决策失误，致使公司损失惨重。","py":"Guǎnlǐ céng juécè shīwù, zhìshǐ gōngsī sǔnshī cǎnzhòng.","en":"Errors in management decision-making caused the company to suffer severe losses."},{"cn":"连日暴雨致使多条道路中断。","py":"Lián rì bàoyǔ zhìshǐ duō tiáo dàolù zhōngduàn.","en":"Continuous days of heavy rain caused multiple roads to be cut off."},{"cn":"信息泄露致使数万用户受到影响。","py":"Xìnxī xìelòu zhìshǐ shù wàn yònghù shòudào yǐngxiǎng.","en":"The information leak caused tens of thousands of users to be affected."}]},{"title":"以至于/以致 (Result Connector: 'To the point that / So much so that')","pattern":"[escalating situation]，以至于/以致 [extreme or unintended consequence]","explanation":"Both connectors introduce a consequence that was excessive or unintended. 以至于 is slightly more colloquial and can introduce positive or negative outcomes; 以致 is more formal and typically negative.","examples":[{"cn":"他废寝忘食地工作，以至于身体严重透支。","py":"Tā fèiqǐn wàng shí de gōngzuò, yǐzhìyú shēntǐ yánzhòng tòuzhī.","en":"He worked so hard he forgot to eat and sleep, to the point that his health was severely overtaxed."},{"cn":"双方分歧过大，以致谈判彻底破裂。","py":"Shuāngfāng fēnqí guòdà, yǐzhì tánpàn chèdǐ pòliè.","en":"The differences between the two sides were too great, so much so that negotiations broke down completely."},{"cn":"噪音扰人，以至于居民无法正常休息。","py":"Zàoyīn rǎo rén, yǐzhìyú jūmín wúfǎ zhèngcháng xiūxi.","en":"The noise was so disruptive that residents were unable to rest normally."}]},{"title":"莫非 (Rhetorical Doubt: 'Could it be that… / Surely not')","pattern":"莫非 [surprising or doubted proposition]？","explanation":"A formal rhetorical question marker used to express surprise, suspicion, or disbelief about a situation. It expects the answer to be 'no' but leaves open the troubling possibility.","examples":[{"cn":"他至今未回消息，莫非出了什么事？","py":"Tā zhìjīn wèi huí xiāoxi, mòfēi chūle shénme shì?","en":"He still hasn't responded — could it be that something has happened to him?"},{"cn":"莫非你从未听说过这段历史？","py":"Mòfēi nǐ cónglái wèi tīngshuōguò zhè duàn lìshǐ?","en":"Surely you have heard of this period of history?"},{"cn":"事情进展如此顺利，莫非其中另有隐情？","py":"Shìqing jìnzhǎn rúcǐ shùnlì, mòfēi qízhōng lìng yǒu yǐnqíng?","en":"Things are going so smoothly — could there be something hidden behind the scenes?"}]},{"title":"不妨 (Tentative Suggestion: 'It wouldn't hurt to / You may as well')","pattern":"不妨 [suggested action]","explanation":"A mild, polite suggestion meaning 'it wouldn't hurt to' or 'feel free to'. Used to propose an option without pressure, often in advisory or analytical writing.","examples":[{"cn":"如有疑问，不妨直接联系相关部门。","py":"Rú yǒu yíwèn, bùfáng zhíjiē liánxì xiāngguān bùmén.","en":"If you have questions, you may as well contact the relevant department directly."},{"cn":"面对困境，不妨换个角度思考问题。","py":"Miànduì kùnjìng, bùfáng huàn gè jiǎodù sīkǎo wèntí.","en":"When facing difficulties, it wouldn't hurt to consider the problem from a different angle."},{"cn":"在做决定之前，不妨广泛征求各方意见。","py":"Zài zuò juédìng zhīqián, bùfáng guǎngfàn zhēngqiú gèfāng yìjiàn.","en":"Before making a decision, you may as well solicit opinions widely from all parties."}]},{"title":"何尝 (Rhetorical Denial: 'It's not as if / When did… ever')","pattern":"何尝 + [negated verb phrase] / 何尝不 + [positive verb phrase]","explanation":"A literary rhetorical device. 何尝不 means 'who has never / it is not as if one hasn't', implying a shared or suppressed truth. Used to express that something is universally true or deeply felt.","examples":[{"cn":"我何尝不想回家，只是身不由己。","py":"Wǒ hécháng bù xiǎng huí jiā, zhǐshì shēn bù yóu jǐ.","en":"It's not as if I don't want to go home — I simply have no control over my own situation."},{"cn":"他们何尝没有努力过，只是命运弄人。","py":"Tāmen hécháng méiyǒu nǔlì guò, zhǐshì mìngyùn nòng rén.","en":"It's not as if they never tried hard — fate simply toyed with them."},{"cn":"这种压力，旁人何尝能够体会？","py":"Zhè zhǒng yālì, pángrén hécháng nénggòu tǐhuì?","en":"As for this kind of pressure, when could outsiders ever truly understand it?"}]},{"title":"姑且 (Provisional Acceptance: 'For now / Let's tentatively')","pattern":"姑且 [provisional action or assumption]","explanation":"Means 'for the time being' or 'let us tentatively accept this', used to set aside a point provisionally. Common in academic and analytical writing to bracket an assumption before proceeding.","examples":[{"cn":"姑且不论这种方法的优劣，其可行性本身就值得怀疑。","py":"Gūqiě bù lùn zhè zhǒng fāngfǎ de yōuliè, qí kěxíngxìng běnshēn jiù zhídé huáiyí.","en":"Setting aside for now whether this method is good or bad, its feasibility itself is worth questioning."},{"cn":"我们姑且接受这一假设，继续推演下去。","py":"Wǒmen gūqiě jiēshòu zhè yī jiǎshè, jìxù tuīyǎn xià qù.","en":"Let us tentatively accept this hypothesis and continue with the deduction."},{"cn":"他的话姑且听之，切不可奉为真理。","py":"Tā de huà gūqiě tīng zhī, qiè bùkě fèng wéi zhēnlǐ.","en":"His words may be heard provisionally, but must never be taken as gospel truth."}]},{"title":"反之 (Logical Reversal: 'Conversely / On the contrary')","pattern":"[stated condition or result]；反之，[opposite condition or result]","explanation":"A formal discourse connector introducing a logically opposite scenario or conclusion. It mirrors the structure of the preceding clause and is common in argumentative essays.","examples":[{"cn":"政策得当则经济繁荣；反之，则可能导致社会动荡。","py":"Zhèngcè dédàng zé jīngjì fánróng; fǎn zhī, zé kěnéng dǎozhì shèhuì dòngdàng.","en":"Sound policy leads to economic prosperity; conversely, it may lead to social unrest."},{"cn":"信任能促进合作；反之，猜疑只会加深隔阂。","py":"Xìnrèn néng cùjìn hézuò; fǎn zhī, cāiyí zhǐ huì jiāshēn géhé.","en":"Trust promotes cooperation; conversely, suspicion only deepens the divide."},{"cn":"勤奋者终有所成；反之，懒惰者必将一事无成。","py":"Qínfèn zhě zhōng yǒu suǒ chéng; fǎn zhī, lǎnduò zhě bì jiāng yī shì wú chéng.","en":"The diligent will ultimately achieve something; conversely, the lazy will inevitably accomplish nothing."}]},{"title":"进而 (Progressive Addition: 'And furthermore / Going further to')","pattern":"[initial action or state]，进而 [further action or deeper consequence]","explanation":"Marks a logical step forward from an initial action or conclusion to a more advanced one. Implies the second step builds directly upon and goes beyond the first.","examples":[{"cn":"他掌握了基础知识，进而开始探索前沿领域。","py":"Tā zhǎngwòle jīchǔ zhīshi, jìn'ér kāishǐ tànsuǒ qiányán lǐngyù.","en":"He mastered the foundational knowledge and then went further to explore cutting-edge fields."},{"cn":"改革推动了经济发展，进而提高了人民的生活水平。","py":"Gǎigé tuīdòngle jīngjì fāzhǎn, jìn'ér tígāole rénmín de shēnghuó shuǐpíng.","en":"Reform drove economic development and, going further, raised the living standards of the people."},{"cn":"我们需要先建立共识，进而制定具体方案。","py":"Wǒmen xūyào xiān jiànlì gòngshí, jìn'ér zhìdìng jùtǐ fāng'àn.","en":"We need to first build consensus, and from there go further to formulate concrete plans."}]},{"title":"从而 (Result/Purpose Connector: 'Thereby / Thus achieving')","pattern":"[action or method]，从而 [intended result or logical consequence]","explanation":"Connects a method or cause to its resulting purpose or effect, with the sense of 'thereby' or 'and in so doing'. More formal than 因此 and implies the result flows directly from deliberate action.","examples":[{"cn":"该技术大幅降低了生产成本，从而增强了产品的市场竞争力。","py":"Gāi jìshù dàfú jiàngdīle shēngchǎn chéngběn, cóng'ér zēngqiángle chǎnpǐn de shìchǎng jìngzhēnglì.","en":"The technology significantly reduced production costs, thereby enhancing the product's market competitiveness."},{"cn":"双方签署了协议，从而为长期合作奠定了基础。","py":"Shuāngfāng qiānshǔle xiéyì, cóng'ér wèi chángqī hézuò diàndìngle jīchǔ.","en":"Both parties signed the agreement, thereby laying the foundation for long-term cooperation."},{"cn":"加强监管有助于遏制腐败，从而提升政府公信力。","py":"Jiāqiáng jiāngǎn yǒuzhù yú èzhì fǔbài, cóng'ér tíshēng zhèngfǔ gōngxìnlì.","en":"Strengthening oversight helps curb corruption, thereby enhancing the government's credibility."}]}],"7":[{"title":"Concessive Subordination with 固然…但/却","pattern":"固然 [conceded fact], 但/却 [contrasting main point]","explanation":"A formal written-register concessive structure meaning 'it is admittedly true that…, but…'. Stronger and more literary than 虽然…但是; typically appears in argumentative essays and editorials.","examples":[{"cn":"经济发展固然重要，但生态环境的保护同样不可忽视。","py":"Jīngjì fāzhǎn gùrán zhòngyào, dàn shēngtài huánjìng de bǎohù tóngyàng bùkě hūshì.","en":"Economic development is admittedly important, but the protection of the ecological environment is equally impossible to ignore."},{"cn":"他的才华固然出众，却缺乏将理想付诸实践的毅力。","py":"Tā de cáihuá gùrán chūzhòng, què quēfá jiāng lǐxiǎng fùzhū shíjiàn de yìlì.","en":"His talent is admittedly outstanding, yet he lacks the perseverance to turn ideals into practice."}]},{"title":"Rhetorical Intensifier 何尝…不/非","pattern":"何尝 + 不/非 + [verb/adjective phrase]","explanation":"A classical-derived rhetorical negative meaning 'it is not as if…has never' or 'who among us has not…'. Used to imply universal shared experience with emotional resonance; strictly 书面语.","examples":[{"cn":"身处异乡的人，何尝不思念故土？","py":"Shēnchǔ yìxiāng de rén, hécháng bù sīniàn gùtǔ?","en":"For those living far from home, who has not longed for their native land?"},{"cn":"面对如此困境，我何尝不想放弃，然而责任使我坚持了下来。","py":"Miànduì rúcǐ kùnjìng, wǒ hécháng bù xiǎng fàngqì, rán'ér zérèn shǐ wǒ jiānchí le xiàlái.","en":"Faced with such a predicament, it's not as if I never wanted to give up — yet responsibility kept me going."}]},{"title":"Proportional Correlation 越…越…","pattern":"随着 [X increasing], [Y] 越来越 [adjective/verb]","explanation":"An advanced variant of the basic 越…越… structure, combining 随着 to express a formal cause-and-effect proportion in written discourse. Conveys dynamic, ongoing correlation in academic or policy contexts.","examples":[{"cn":"随着全球化进程的加深，各国之间的相互依存关系越来越密切。","py":"Suízhe quánqiúhuà jìnchéng de jiāshēn, gèguó zhījiān de xiānghù yīcún guānxi yuèlái yuè mìqiē.","en":"As the process of globalization deepens, the interdependence among nations becomes ever closer."},{"cn":"随着人工智能技术的成熟，传统行业所面临的挑战越来越不容小觑。","py":"Suízhe réngōng zhìnéng jìshù de chéngshú, chuántǒng hángyè suǒ miànlín de tiǎozhàn yuèlái yuè bùróng xiǎoqù.","en":"As artificial intelligence technology matures, the challenges facing traditional industries are increasingly impossible to underestimate."}]},{"title":"Emphatic Fronting with 正是…才/方","pattern":"正是 [reason/agent], 才/方 [result/action]","explanation":"A formal cleft-like construction that foregrounds the true cause or agent, translated as 'it is precisely…that…'. 方 is more literary than 才; both are common in formal speeches and written arguments.","examples":[{"cn":"正是几代科学家的不懈努力，才使这项技术得以在今天实现。","py":"Zhèng shì jǐ dài kēxuéjiā de bùxiè nǔlì, cái shǐ zhè xiàng jìshù déyǐ zài jīntiān shíxiàn.","en":"It is precisely the tireless efforts of several generations of scientists that have made this technology achievable today."},{"cn":"正是对真理的执着追求，方成就了他在学术界的崇高地位。","py":"Zhèng shì duì zhēnlǐ de zhízhuó zhuīqiú, fāng chéngjiù le tā zài xuéshùjiè de chónggāo dìwèi.","en":"It is precisely his tenacious pursuit of truth that forged his esteemed standing in academia."}]},{"title":"Classical Conditional 苟/倘若…则","pattern":"苟/倘若 [condition], 则 [consequence]","explanation":"Literary conditionals with a formal, classical flavor. 苟 (if, provided that) appears in legal, philosophical, and formal written texts; 则 as the apodosis marker is preferred in 书面语 over 就.","examples":[{"cn":"苟能以诚相待，则合作自可长久。","py":"Gǒu néng yǐ chéng xiāngdài, zé hézuò zì kě cháng jiǔ.","en":"Provided that one can treat the other with sincerity, a lasting partnership will naturally follow."},{"cn":"倘若各方均能恪守协议，则地区局势或可趋于稳定。","py":"Tǎngruò gèfāng jūn néng kèshǒu xiéyì, zé dìqū júshì huò kě qūyú wěndìng.","en":"If all parties can strictly abide by the agreement, the regional situation may well trend toward stability."}]},{"title":"Passive-Adversative Construction 为…所","pattern":"[Subject] 为 [agent] 所 [verb]","explanation":"A classical passive construction meaning 'to be [verb-ed] by [agent]', carrying a formal or literary register often with an adversative (undesirable) nuance. Equivalent to 被 passives but far more elevated in register.","examples":[{"cn":"这一观点长期以来为学界所忽视，直至近年方引起广泛关注。","py":"Zhè yī guāndiǎn chángqī yǐlái wéi xuéjiè suǒ hūshì, zhízhì jìnnián fāng yǐnqǐ guǎngfàn guānzhù.","en":"This viewpoint was long overlooked by academia and only in recent years has it attracted widespread attention."},{"cn":"他的一生为命运所捉弄，却始终未曾放弃心中的理想。","py":"Tā de yīshēng wéi mìngyùn suǒ zhuōnòng, què shǐzhōng wèicéng fàngqì xīnzhōng de lǐxiǎng.","en":"His whole life was toyed with by fate, yet he never once abandoned the ideals in his heart."}]},{"title":"Adversative Pivot 非但/不但…反而","pattern":"非但/不但 [negated expected outcome], 反而 [contrary result]","explanation":"Expresses that rather than producing the expected result, the opposite occurred. 非但 is more formal and written than 不但 in this pattern; 反而 signals the contrary outcome. Common in critical analysis.","examples":[{"cn":"这项政策非但没有缓解矛盾，反而加剧了社会的分裂。","py":"Zhè xiàng zhèngcè fēidàn méiyǒu huǎnjiě máodùn, fǎn'ér jiājù le shèhuì de fēnliè.","en":"This policy not only failed to ease the conflict but actually exacerbated social division."},{"cn":"过度的管制非但不能促进创新，反而会抑制企业的活力。","py":"Guòdù de guǎnzhì fēidàn bùnéng cùjìn chuàngxīn, fǎn'ér huì yìzhì qǐyè de huólì.","en":"Excessive regulation not only fails to promote innovation but in fact suppresses the vitality of enterprises."}]},{"title":"Nominal Apposition with 之","pattern":"[Noun phrase] 之 [relational noun], [comment]","explanation":"Classical 之 replacing 的 in formal or literary noun modification, especially in fixed four-character patterns and set phrases. Signals elevated register in academic writing, official documents, and literary prose.","examples":[{"cn":"此乃百年难遇之机遇，务必珍惜把握。","py":"Cǐ nǎi bǎinián nányù zhī jīyù, wùbì zhēnxī bǎwò.","en":"This is an opportunity that comes once in a hundred years; one must cherish and seize it."},{"cn":"语言乃文化传承之载体，其保护意义不容低估。","py":"Yǔyán nǎi wénhuà chuánchéng zhī zǎitǐ, qí bǎohù yìyì bùróng dīgū.","en":"Language is the vehicle of cultural transmission; the significance of its preservation must not be underestimated."},{"cn":"诚信乃立身处世之根本。","py":"Chéngxìn nǎi lìshēn chǔshì zhī gēnběn.","en":"Integrity is the foundation of conducting oneself in the world."}]},{"title":"Modal Epistemic Hedging 或/或许…未必","pattern":"[Proposition A] 或许/未必 [negated assumption B]","explanation":"A sophisticated hedging pattern used in formal argument to challenge received wisdom without overstating certainty. 未必 (not necessarily) paired with 或许 (perhaps) projects an analytical, measured voice typical of academic prose.","examples":[{"cn":"舆论的强烈反应或许表明公众对此并非漠然，但热度未必能转化为持久的行动力。","py":"Yúlùn de qiángliè fǎnyìng huòxǔ biǎomíng gōngzhòng duì cǐ bìng fēi mòrán, dàn rèdù wèibì néng zhuǎnhuà wéi chíjiǔ de xíngdònglì.","en":"The strong public reaction perhaps indicates that people are not indifferent, but that intensity may not necessarily translate into sustained capacity for action."},{"cn":"技术的进步固然可观，却未必能解决所有由人性弱点引发的问题。","py":"Jìshù de jìnbù gùrán kěguān, què wèibì néng jiějué suǒyǒu yóu rénxìng ruòdiǎn yǐnfā de wèntí.","en":"Technological progress is admittedly impressive, yet it may not necessarily resolve every problem arising from human weakness."}]},{"title":"Resultative Complement with Degree 到…的程度","pattern":"[Verb/Adjective] 到 [了] [such a degree] 的程度","explanation":"An advanced resultative construction that formally specifies the extent of a state or action, common in written analysis and academic description. More precise and formal than simply 得很 or 极了.","examples":[{"cn":"两国之间的贸易摩擦已激化到了难以通过谈判化解的程度。","py":"Liǎng guó zhījiān de màoyì mócā yǐ jīhuà dào le nányǐ tōngguò tánpàn huàjiě de chéngdù.","en":"The trade friction between the two countries has escalated to a degree that is difficult to resolve through negotiation."},{"cn":"城市的扩张速度之快，已到了生态系统难以自我修复的程度。","py":"Chéngshì de kuòzhāng sùdù zhī kuài, yǐ dào le shēngtài xìtǒng nányǐ zìwǒ xiūfù de chéngdù.","en":"The pace of urban expansion has reached a degree at which ecosystems can barely regenerate themselves."}]},{"title":"Concessive Relative 尽管如此/即便如此","pattern":"[Preceding context]. 尽管如此/即便如此, [contrasting assertion]","explanation":"Sentence-initial pivot phrases meaning 'even so' or 'despite all this', used to acknowledge prior complexity before asserting a counter-position. More formal than 但是/然而 and explicitly reference the full preceding argument; common in conclusion paragraphs.","examples":[{"cn":"改革面临诸多阻力，各方利益难以协调。尽管如此，推进改革的决心不应动摇。","py":"Gǎigé miànlín zhūduō zǔlì, gèfāng lìyì nányǐ xiétiáo. Jǐnguǎn rúcǐ, tuījìn gǎigé de juéxīn bù yīng dòngyáo.","en":"Reform faces numerous obstacles and the interests of various parties are difficult to reconcile. Even so, the resolve to push forward with reform must not waver."},{"cn":"目前证据尚不充分，结论仍有争议。即便如此，我们也不能对潜在的风险视而不见。","py":"Mùqián zhèngjù shàng bù chōngfèn, jiélùn réng yǒu zhēngyì. Jíbiàn rúcǐ, wǒmen yě bùnéng duì qiánzài de fēngxiǎn shì ér bù jiàn.","en":"Current evidence is still insufficient and conclusions remain contested. Even so, we cannot turn a blind eye to the potential risks."}]},{"title":"Classical Existential-Pivotal 有…者","pattern":"有 [category noun] 者, [predicate about them]","explanation":"A classical construction meaning 'there are those who…' or 'some [category] exists such that…', creating a formal, literary tone. Used to introduce a type of person, thing, or situation for further elaboration; equivalent to 有的人 but far more elevated.","examples":[{"cn":"有学者者，博览群书而不求甚解；有学者者，精研一隅而触类旁通。","py":"Yǒu xuézhě zhě, bólǎn qúnshū ér bù qiú shèn jiě; yǒu xuézhě zhě, jīng yán yī yú ér chùlèi páng tōng.","en":"Some scholars read widely without seeking deep understanding; others master one narrow field and from it illuminate all others."},{"cn":"有论者谓，此制度已不适应当代社会之需求，亟需根本性的变革。","py":"Yǒu lùnzhě wèi, cǐ zhìdù yǐ bù shìyìng dāngdài shèhuì zhī xūqiú, jí xū gēnběnxìng de biàngé.","en":"There are commentators who argue that this system no longer meets the needs of contemporary society and requires fundamental transformation."}]}],"8":[{"title":"Classical Causal Connector 盖 (introductory 'for / the reason being')","pattern":"盖 + [explanatory clause]","explanation":"A 文言 particle placed at the start of a sentence or clause to introduce a reason or underlying principle. It is confined to formal written prose and lends an authoritative, classical tone not found in conversational Chinese.","examples":[{"cn":"此法久行而弊端丛生，盖制度设计之初未曾虑及人性之复杂也。","py":"Cǐ fǎ jiǔ xíng ér bìduān cóngshēng, gài zhìdù shèjì zhī chū wèi céng lǜ jí rénxìng zhī fùzá yě.","en":"This policy has been in force for a long time yet abuses have multiplied — the reason being that its designers never considered the complexity of human nature."},{"cn":"学而不思则罔，盖知识若无反省之功，终成死物耳。","py":"Xué ér bù sī zé wǎng, gài zhīshi ruò wú fǎnxǐng zhī gōng, zhōng chéng sǐwù ěr.","en":"Learning without reflection leads to confusion — for knowledge without the effort of introspection will ultimately become inert matter."}]},{"title":"Literary Concessive 固然…然而/但 (admittedly…yet)","pattern":"固然 + [conceded point]，然而/但 + [counterpoint]","explanation":"固然 concedes a point more emphatically and formally than 虽然; paired with 然而 it creates a balanced, essay-style rhetorical structure favoured in op-eds, legal argument, and academic writing.","examples":[{"cn":"经济增长固然重要，然而以牺牲生态环境为代价换取的发展终将难以为继。","py":"Jīngjì zēngzhǎng gùrán zhòngyào, rán'ér yǐ xīshēng shēngtài huánjìng wéi dàijià huànqǔ de fāzhǎn zhōng jiāng nán yǐ wéijì.","en":"Admittedly economic growth is important, yet development obtained at the cost of the ecological environment will ultimately prove unsustainable."},{"cn":"个人自由固然可贵，但自由若无边界，便会侵害他人之权利。","py":"Gèrén zìyóu gùrán kěguì, dàn zìyóu ruò wú biānjiè, biàn huì qīnhài tārén zhī quánlì.","en":"Individual freedom is admittedly precious, but freedom without limits will encroach upon the rights of others."}]},{"title":"Formal Additive Connector 不独…亦 (not only…also)","pattern":"不独 + [A]，亦 + [B]","explanation":"A more literary and elevated alternative to 不但…也; 不独 carries a classical flavour and is used in formal essays, editorials, and speeches to present a cumulative argument.","examples":[{"cn":"这场变革不独影响了经济格局，亦从根本上重塑了社会结构。","py":"Zhè chǎng biàngé bù dú yǐngxiǎngle jīngjì géjú, yì cóng gēnběn shàng chóngsùle shèhuì jiégòu.","en":"This transformation not only affected the economic landscape, but also fundamentally reshaped the social structure."},{"cn":"汉字之美，不独在于其视觉造型，亦在于数千年文化积淀所赋予的深厚意涵。","py":"Hànzì zhī měi, bù dú zàiyú qí shìjué zàoxíng, yì zàiyú shù qiānnián wénhuà jīdiàn suǒ fùyǔ de shēnhòu yìhán.","en":"The beauty of Chinese characters lies not only in their visual form, but also in the profound meaning endowed by thousands of years of cultural accumulation."}]},{"title":"Classical Passive 为…所 (be done by)","pattern":"为 + [agent] + 所 + [verb]","explanation":"A classical passive construction preserved in formal modern Chinese, particularly in written and legal registers. It is more emphatic than the colloquial 被 construction and often implies the subject is somewhat at the mercy of the agent.","examples":[{"cn":"这部作品为后世所推崇，被奉为古典文学之典范。","py":"Zhè bù zuòpǐn wéi hòushì suǒ tuīchóng, bèi fèng wéi gǔdiǎn wénxué zhī diǎnfàn.","en":"This work was held in high esteem by later generations and revered as a model of classical literature."},{"cn":"改革之初，他的主张为守旧派所压制，几乎无从施展。","py":"Gǎigé zhī chū, tā de zhǔzhāng wéi shǒujiùpài suǒ yāzhì, jīhū wú cóng shīzhǎn.","en":"At the outset of the reforms, his proposals were suppressed by conservatives, leaving him almost no room to act."}]},{"title":"Emphatic Rhetorical Negation 岂…乎/哉 (could it possibly be that…?)","pattern":"岂 + [proposition] + 乎/哉/耶","explanation":"A rhetorical question structure inherited from classical Chinese; the implied answer is always 'no'. It appears in formal argumentation, literary prose, and public speeches to forcefully reject a proposition.","examples":[{"cn":"吾辈读书求学，岂仅为一纸文凭乎？","py":"Wúbèi dúshū qiúxué, qǐ jǐn wèi yī zhǐ wénpíng hū?","en":"Can it be that we study and pursue learning merely for a single piece of paper called a diploma?"},{"cn":"面对如此不公，我们岂能袖手旁观哉！","py":"Miànduì rúcǐ bùgōng, wǒmen qǐ néng xiùshǒupángguān zāi!","en":"In the face of such injustice, could we possibly stand by with arms folded and do nothing?"},{"cn":"千里之行始于足下，岂有不积跬步而能至远方者哉？","py":"Qiānlǐ zhī xíng shǐ yú zú xià, qǐ yǒu bù jī kuǐbù ér néng zhì yuǎnfāng zhě zāi?","en":"A journey of a thousand li begins with a single step — could there ever be anyone who reaches a distant destination without accumulating small steps?"}]},{"title":"Conditional Subjunctive 倘若/倘使…则/便 (should it be that…then)","pattern":"倘若/倘使 + [hypothetical condition]，则/便 + [consequence]","explanation":"More formal and literary than 如果…就; 倘若 and 倘使 introduce hypothetical or counterfactual conditions in written prose, legal documents, and deliberate speech, conveying a sense of measured, considered reasoning.","examples":[{"cn":"倘若当年他选择留在国内，则中国现代物理学的发展或将走上另一条道路。","py":"Tǎngruò dāngnián tā xuǎnzé liú zài guónèi, zé Zhōngguó xiàndài wùlǐxué de fāzhǎn huò jiāng zǒushàng lìng yī tiáo dàolù.","en":"Had he chosen to remain in the country at that time, the development of modern physics in China might have taken an entirely different path."},{"cn":"倘使此议案获得通过，便将对现行税制产生深远影响。","py":"Tǎngshǐ cǐ yì'àn huòdé tōngguò, biàn jiāng duì xiànxíng shuìzhì chǎnshēng shēnyuǎn yǐngxiǎng.","en":"Should this bill pass, it would have far-reaching implications for the existing tax system."}]},{"title":"Formal Adversative Pivot 然则 (that being the case, then / but then)","pattern":"[preceding context]。然则 + [inference or new question]","explanation":"A classical connector combining 然 ('that being so') and 则 ('then'); it draws an inference from what was just said or pivots to a resulting question. It is restricted to formal written Chinese and signals logical transition in argumentation.","examples":[{"cn":"现行制度存在诸多弊端，各方对此已无异议。然则改革之路究竟如何推进，方为当务之急。","py":"Xiànxíng zhìdù cúnzài zhūduō bìduān, gèfāng duì cǐ yǐ wú yìyì. Rán zé gǎigé zhī lù jiūjìng rúhé tuījìn, fāng wéi dāngwù zhī jí.","en":"There is now no dispute that the current system has numerous defects. That being the case, how exactly the path of reform is to be advanced is the most pressing matter."},{"cn":"民众渴望公正，政府亦声称以公正为本。然则现实中种种不平等现象，又作何解释？","py":"Mínzhòng kěwàng gōngzhèng, zhèngfǔ yì chēngchēng yǐ gōngzhèng wéi běn. Rán zé xiànshí zhōng zhǒngzhǒng bù píngděng xiànxiàng, yòu zuò hé jiěshì?","en":"The people yearn for justice, and the government also claims to be rooted in justice. That being so, how then are the various inequalities in reality to be explained?"}]},{"title":"Intensified Limit 无不 / 莫不 (there is none that does not / all without exception)","pattern":"无不/莫不 + [verb phrase]","explanation":"Double negation creating universal affirmation; 莫不 is more classical while 无不 appears in both formal and modern written registers. Both assert that every member of a set exhibits the stated quality, carrying greater rhetorical weight than 都.","examples":[{"cn":"与会代表无不对这一创举表示高度赞赏。","py":"Yǔhuì dàibiǎo wú bù duì zhè yī chuàngjǔ biǎoshì gāodù zànshǎng.","en":"Without exception, every representative at the meeting expressed high praise for this pioneering initiative."},{"cn":"历史上凡成大事者，莫不经历过艰难困苦的磨砺。","py":"Lìshǐ shàng fán chéng dàshì zhě, mò bù jīnglìguò jiānnán kùnkǔ de mólì.","en":"Throughout history, all those who have accomplished great things have without exception been tempered by hardship and adversity."},{"cn":"这部史诗巨著问世之后，读者无不为其宏大叙事所震撼。","py":"Zhè bù shǐshī jùzhù wènshì zhīhòu, dúzhě wú bù wèi qí hóngdà xùshì suǒ zhènhàn.","en":"After this epic masterpiece was published, every reader without exception was struck by the grandeur of its narrative."}]},{"title":"Classical Degree Complement with 之至 / 极矣 (to the utmost / in the extreme)","pattern":"[adjective/verb] + 之至 / [adjective] + 极矣","explanation":"Literary degree intensifiers appended after an adjective or stative verb; 之至 means 'to the utmost degree' and 极矣 signals 'this is the extreme'. Both are restricted to formal or semi-literary written prose and add rhetorical gravity.","examples":[{"cn":"此举之鲁莽，令人遗憾之至。","py":"Cǐ jǔ zhī lǔmǎng, lìng rén yíhàn zhī zhì.","en":"The recklessness of this action is a source of the deepest regret."},{"cn":"其言辞之犀利、逻辑之严密，令对手狼狈极矣。","py":"Qí yáncí zhī xīlì, luójí zhī yánmì, lìng duìshǒu lángbèi jí yǐ.","en":"The sharpness of his words and the rigour of his logic left his opponent in the most extreme embarrassment."}]},{"title":"Formal Concessive with Scalar Emphasis 尚且…何况 (even X…let alone Y)","pattern":"[more extreme case] + 尚且 + [predicate A]，何况 + [less extreme case] + [predicate B/implied]","explanation":"A rhetorical a fortiori structure arguing from the harder case to the easier: 'if even X cannot manage A, how much less can Y'. It appears in formal argumentation, legal briefs, and literary prose to clinch a point by analogy.","examples":[{"cn":"专业学者尚且对这一问题难以达成共识，何况普通民众。","py":"Zhuānyè xuézhě shàngqiě duì zhè yī wèntí nányǐ dáchéng gòngshí, hékuàng pǔtōng mínzhòng.","en":"Even professional scholars find it hard to reach consensus on this issue — let alone the general public."},{"cn":"古代帝王尚且不能违背天道而长治久安，何况今日之独裁者乎？","py":"Gǔdài dìwáng shàngqiě bù néng wéibèi tiāndào ér cháng zhì jiǔ ān, hékuàng jīnrì zhī dúcáizhě hū?","en":"Even the emperors of antiquity could not violate the natural order and maintain long-lasting peace and stability — how much less so today's autocrats?"}]},{"title":"Formal Inferential 由此可见 / 可见一斑 (from this one can see / one gets a glimpse)","pattern":"由此可见，[conclusion] / [preceding context]，可见一斑","explanation":"Discourse-level connectors used in formal writing to draw a conclusion or illustrative inference; 可见一斑 specifically means that a small detail reveals a larger truth (literally 'one can see a single spot on the leopard'), used when the evidence presented is partial but representative.","examples":[{"cn":"该公司年营收增长率连续五年超过30%，由此可见其商业模式之强大生命力。","py":"Gāi gōngsī nián yíngshōu zēngzhǎng lǜ liánxù wǔ nián chāoguò 30%, yóucǐ kějiàn qí shāngyè móshì zhī qiángdà shēngmìnglì.","en":"The company's annual revenue growth rate has exceeded 30% for five consecutive years; from this one can see the powerful vitality of its business model."},{"cn":"仅此一封家书，作者对故土深情之重，已可见一斑。","py":"Jǐn cǐ yī fēng jiāshū, zuòzhě duì gùtǔ shēnqíng zhī zhòng, yǐ kě jiàn yī bān.","en":"From this single letter home alone, one already gets a glimpse of how deeply the author cherishes his homeland."}]},{"title":"Literary Resultative with 以致/以至于 (so much so that / to the point where, with negative result)","pattern":"[cause/degree escalation]，以致/以至于 + [undesirable result]","explanation":"以致 and 以至于 introduce an extreme or unintended consequence, almost always negative or regrettable; they differ from 所以 (neutral causation) and 导致 (neutral result) by foregrounding excess or inadvertence. 以致 is more formal and terse.","examples":[{"cn":"他一味追求形式上的完美，以致项目迟迟无法如期交付。","py":"Tā yīwèi zhuīqiú xíngshì shàng de wánměi, yǐzhì xiàngmù chíchí wúfǎ rúqī jiāofù.","en":"He pursued formal perfection single-mindedly, to the point where the project could not be delivered on schedule."},{"cn":"双方积怨日深，以至于最终诉诸法律，对簿公堂。","py":"Shuāngfāng jī yuàn rì shēn, yǐzhìyú zuìzhōng sùzhū fǎlǜ, duìbù gōngtáng.","en":"Grievances between the two parties deepened day by day, so much so that they ultimately resorted to the law and faced each other in court."},{"cn":"舆论压力持续发酵，以致政府不得不公开就此事作出回应。","py":"Yúlùn yālì chíxù fāxiào, yǐzhì zhèngfǔ bùdébù gōngkāi jiù cǐ shì zuòchū huíyìng.","en":"Public pressure continued to ferment, so much so that the government had no choice but to respond to the matter publicly."}]}],"9":[{"title":"Classical Rhetorical Inversion with 者…也","pattern":"……者，……也","explanation":"A classical Chinese copular structure borrowed into formal modern prose to deliver weighty definitions or judgments. It imparts an authoritative, aphoristic tone found in essays, legal texts, and academic writing.","examples":[{"cn":"真正的勇者，非无畏者，乃知畏而仍前行者也。","py":"Zhēnzhèng de yǒng zhě, fēi wú wèi zhě, nǎi zhī wèi ér réng qiánxíng zhě yě.","en":"A truly courageous person is not one without fear, but one who knows fear and advances nonetheless."},{"cn":"所谓文明者，人与人之间相互尊重之共识也。","py":"Suǒwèi wénmíng zhě, rén yǔ rén zhī jiān xiānghù zūnzhòng zhī gòngshí yě.","en":"What we call civilization is the shared understanding of mutual respect among people."},{"cn":"法律者，社会契约之成文体现也。","py":"Fǎlǜ zhě, shèhuì qìyuē zhī chéngwén tǐxiàn yě.","en":"Law is the codified expression of the social contract."}]},{"title":"Parallel Antithetical Couplets (对仗)","pattern":"A₁B₁C₁，A₂B₂C₂（grammatically and semantically parallel, often antithetical）","explanation":"Formal Chinese writing employs 对仗 — strict syntactic and semantic parallelism between two clauses of equal length — for rhetorical elegance. Mastery requires matching not only grammar but also tone category (平仄) in literary contexts.","examples":[{"cn":"居安思危，处盛虑衰。","py":"Jū ān sī wēi, chǔ shèng lǜ shuāi.","en":"When at peace, contemplate danger; when at the height of prosperity, anticipate decline."},{"cn":"言必信，行必果，此乃立身处世之根本。","py":"Yán bì xìn, xíng bì guǒ, cǐ nǎi lì shēn chǔ shì zhī gēnběn.","en":"Words must be trustworthy, actions must be resolute — this is the foundation of one's conduct in life."},{"cn":"厚积薄发，大智若愚。","py":"Hòu jī bó fā, dà zhì ruò yú.","en":"Accumulate deeply and release sparingly; great wisdom appears as foolishness."}]},{"title":"Concessive Escalation with 固然…但/然","pattern":"固然……，但/然……","explanation":"More formal than 虽然…但是, 固然 concedes a point with an air of intellectual detachment before pivoting to the stronger claim. Common in argumentation, editorials, and academic discourse.","examples":[{"cn":"经济发展固然重要，然生态环境之保护亦不可偏废。","py":"Jīngjì fāzhǎn gùrán zhòngyào, rán shēngtài huánjìng zhī bǎohù yì bùkě piān fèi.","en":"Economic development is certainly important; nevertheless, the protection of the ecological environment must not be neglected either."},{"cn":"技术固然能提升效率，但人文关怀才是社会进步的真正标尺。","py":"Jìshù gùrán néng tíshēng xiàolǜ, dàn rénwén guānhuái cái shì shèhuì jìnbù de zhēnzhèng biāochǐ.","en":"Technology can certainly improve efficiency, but humanistic concern is the true measure of social progress."}]},{"title":"Classical Negative with 非…不可/莫属","pattern":"非……不可 / 非……莫属","explanation":"A double-negative structure with classical roots expressing exclusivity or absolute necessity. 非…不可 means 'cannot but; must'; 非…莫属 means 'none other than… is suited'. Both carry a formal, decisive register.","examples":[{"cn":"要解决这一难题，非集众人之智不可。","py":"Yào jiějué zhè yī nántí, fēi jí zhòng rén zhī zhì bùkě.","en":"To solve this difficult problem, one must pool the collective wisdom of many."},{"cn":"担此重任，非德才兼备者莫属。","py":"Dān cǐ zhòng rèn, fēi dé cái jiān bèi zhě mò shǔ.","en":"To bear this weighty responsibility, none other than a person of both virtue and talent is suited."},{"cn":"此刻，非挺身而出不可，退缩只会酿成更大的悲剧。","py":"Cǐ kè, fēi tǐng shēn ér chū bùkě, tuìsuō zhǐ huì niàngchéng gèng dà de bēijù.","en":"At this moment, one must step forward — retreating will only lead to a greater tragedy."}]},{"title":"Formal Discourse Pivot with 有鉴于此","pattern":"有鉴于此，……；鉴于……，……","explanation":"A high-register transitional phrase meaning 'in view of this / given this consideration'. Used in formal reports, policy documents, and argumentative essays to signal that the preceding evidence now motivates the following proposal or conclusion.","examples":[{"cn":"有鉴于此，相关部门应尽快出台配套政策，以弥补现行法规的不足。","py":"Yǒu jiàn yú cǐ, xiāngguān bùmén yīng jǐnkuài chūtái pèitào zhèngcè, yǐ míbǔ xiànxíng fǎguī de bùzú.","en":"In view of this, the relevant authorities should promptly introduce complementary policies to remedy the deficiencies in current regulations."},{"cn":"鉴于国际形势瞬息万变，我方建议推迟谈判以待时机成熟。","py":"Jiàn yú guójì xíngshì shùnxī wàn biàn, wǒ fāng jiànyì tuīchí tánpàn yǐ dài shíjī chéngshú.","en":"Given the rapidly shifting international situation, our side proposes postponing negotiations until conditions are ripe."}]},{"title":"Classical Conditional with 苟/倘若…则/必","pattern":"苟……，则/必……","explanation":"苟 is a classical conditional particle meaning 'if indeed / provided that', more literary and weighty than 如果. It often appears in moralizing or philosophical arguments. 倘若 is semi-literary and slightly less archaic.","examples":[{"cn":"苟利国家生死以，岂因祸福避趋之。","py":"Gǒu lì guójiā shēng sǐ yǐ, qǐ yīn huò fú bì qū zhī.","en":"If it benefits the nation even at the cost of my life, how could I avoid it merely on account of personal fortune or misfortune?"},{"cn":"苟能持之以恒，则天下无难事。","py":"Gǒu néng chí zhī yǐ héng, zé tiānxià wú nán shì.","en":"If one can truly persevere, then nothing in the world is too difficult."},{"cn":"倘若人人皆能推己及人，则社会矛盾必将大为减少。","py":"Tǎngruò rén rén jiē néng tuī jǐ jí rén, zé shèhuì máodùn bì jiāng dàwéi jiǎnshǎo.","en":"If everyone could extend consideration from themselves to others, social conflicts would surely diminish greatly."}]},{"title":"Classical Causal Inversion with 盖/盖因","pattern":"盖……（，故/因此……）","explanation":"盖 is a classical particle that introduces a reason or underlying explanation, roughly equivalent to 'the reason is that…' or 'for indeed…'. It signals a learned, authoritative tone and is found in classical-influenced modern essays and formal argumentation.","examples":[{"cn":"此政策之所以难以推行，盖因利益群体盘根错节，牵一发而动全身。","py":"Cǐ zhèngcè zhī suǒyǐ nányǐ tuīxíng, gài yīn lìyì qúntǐ pán gēn cuò jié, qiān yī fà ér dòng quán shēn.","en":"The reason this policy is so difficult to implement is precisely that interest groups are deeply entangled — pulling one hair moves the whole body."},{"cn":"古人重礼，盖礼者，人与禽兽之分野也。","py":"Gǔ rén zhòng lǐ, gài lǐ zhě, rén yǔ qínshòu zhī fēnyě yě.","en":"The ancients valued ritual propriety, for ritual is precisely what distinguishes humankind from beasts."},{"cn":"其文笔隽永，盖得益于数十年如一日的广泛阅读。","py":"Qí wénbǐ juànyǒng, gài déyì yú shùshí nián rú yī rì de guǎngfàn yuèdú.","en":"Her writing style is elegant and enduring, for it derives from decades of uninterrupted broad reading."}]},{"title":"Rhetorical Question as Refutation with 岂…乎/哉","pattern":"岂……乎？ / 岂……哉？","explanation":"A classical rhetorical question structure that forcefully denies or refutes. 岂 introduces the rhetorical question ('Could it be that…? / How could…?') and the final particle 乎 or 哉 adds classical gravity. Common in polemic essays and elevated speech.","examples":[{"cn":"吾辈生于斯，长于斯，岂能坐视家园沦落而无动于衷哉？","py":"Wú bèi shēng yú sī, zhǎng yú sī, qǐ néng zuòshì jiāyuán lúnluò ér wú dòng yú zhōng zāi?","en":"We were born here and raised here — how could we stand idly by and watch our homeland decline without being moved?"},{"cn":"人而无信，岂能立于天地之间乎？","py":"Rén ér wú xìn, qǐ néng lì yú tiāndì zhī jiān hū?","en":"A person without integrity — how could they stand upright between heaven and earth?"},{"cn":"区区小挫，岂足以令志士灰心哉？","py":"Qūqū xiǎo cuò, qǐ zú yǐ lìng zhìshì huīxīn zāi?","en":"A mere trifling setback — how could it be enough to discourage a person of ambition?"}]},{"title":"Progressive Intensification with 不仅…更/尤","pattern":"不仅……，更/尤……；不唯……，抑且……","explanation":"While 不仅…而且 is standard, advanced writers use 不唯…抑且 or 不仅…尤为 to signal a more refined escalation. 抑且 is semi-classical and adds a literary flavor absent from everyday discourse.","examples":[{"cn":"这场改革不唯触动了既有的利益格局，抑且重塑了整个社会的价值取向。","py":"Zhè chǎng gǎigé bù wéi chùdòng le jì yǒu de lìyì géjú, yì qiě chóng sù le zhěnggè shèhuì de jiàzhí qǔxiàng.","en":"This reform not only disturbed the existing configuration of vested interests, but moreover reshaped the value orientation of the whole society."},{"cn":"他的贡献不仅体现在学术层面，尤在于为后学树立了严谨治学的典范。","py":"Tā de gòngxiàn bùjǐn tǐxiàn zài xuéshù céngmiàn, yóu zàiyú wèi hòu xué shùlì le yánjǐn zhìxué de diǎnfàn.","en":"His contribution manifests not only at the academic level, but especially in having established for future scholars a model of rigorous scholarship."}]},{"title":"Classical Concession-Contrast with 虽…固…，然…终","pattern":"虽……固……，然……终……","explanation":"An elevated three-part structure that concedes a reality (虽…固…, 'though it is indeed the case that…'), then pivots to an ultimate truth (然…终, 'yet in the end…'). The addition of 固 ('indeed/certainly') and 终 ('ultimately') deepens the rhetorical weight beyond the common 虽然…但是.","examples":[{"cn":"文化差异虽固客观存在，然人类对美好生活的向往终无二致。","py":"Wénhuà chāyì suī gù kèguān cúnzài, rán rénlèi duì měihǎo shēnghuó de xiàngwǎng zhōng wú èr zhì.","en":"Cultural differences do indeed objectively exist; yet humanity's yearning for a better life is ultimately the same."},{"cn":"岁月虽固无情，然一代代人的精神传承终将超越时间的消磨。","py":"Suìyuè suī gù wúqíng, rán yī dài dài rén de jīngshén chuánchéng zhōng jiāng chāoyuè shíjiān de xiāomó.","en":"Time is indeed merciless; yet the spiritual inheritance passed down through generations will ultimately transcend time's erosion."}]},{"title":"Formal Existential Highlighting with 存在…的问题/困境","pattern":"（……）存在着……的问题/困境/悖论","explanation":"In formal analytical writing, 存在着 followed by a nominalized VP + 的问题 is used to name systemic issues with precision. Pairing this with abstract nominalizations like 悖论 (paradox), 困境 (dilemma), or 张力 (tension) marks a high academic register.","examples":[{"cn":"现行评价体系存在着激励创新与规避风险之间难以调和的内在张力。","py":"Xiànxíng píngjià tǐxì cúnzàizhe jīlì chuàngxīn yǔ guībì fēngxiǎn zhī jiān nányǐ tiáohé de nèizài zhānglì.","en":"The current evaluation system contains an irreconcilable internal tension between incentivizing innovation and avoiding risk."},{"cn":"全球化进程中存在着发展利益分配不均的深层次结构性困境。","py":"Quánqiú huà jìnchéng zhōng cúnzàizhe fāzhǎn lìyì fēnpèi bùjūn de shēncéngcì jiégòu xìng kùnjìng.","en":"Within the process of globalization there exists a deep-level structural dilemma of unequal distribution of developmental benefits."}]},{"title":"Stylistic Topic-Comment Fronting with Classical 之","pattern":"……之……，……（fronted topic noun phrase using 之 as possessive/linking particle）","explanation":"Advanced writers front complex noun phrases built with classical 之 (as a formal possessive/nominalizer) to create a topic-comment structure that sounds weighty and deliberate. This device compresses what would be a verbose clause into an elegant nominalized phrase and is a hallmark of high-register prose.","examples":[{"cn":"制度之完善与否，直接关乎社会公平之实现。","py":"Zhìdù zhī wánshàn yǔ fǒu, zhíjiē guānhū shèhuì gōngpíng zhī shíxiàn.","en":"Whether a system is sound or not directly bears upon the realization of social justice."},{"cn":"语言之精妙，在于其能以有限之符号，承载无限之思想。","py":"Yǔyán zhī jīngmiào, zàiyú qí néng yǐ yǒuxiàn zhī fúhào, chéngzǎi wúxiàn zhī sīxiǎng.","en":"The exquisiteness of language lies in its ability to carry infinite thought by means of a finite set of symbols."},{"cn":"文明之兴衰，非一朝一夕之功，乃数代人积累与取舍之结果。","py":"Wénmíng zhī xīngshuāi, fēi yī zhāo yī xī zhī gōng, nǎi shù dài rén jīlěi yǔ qǔshě zhī jiéguǒ.","en":"The rise and fall of civilizations is not the achievement of a single morning or evening, but the result of accumulation and choices made across many generations."}]}]};
});
